const gloss=[['形势派','观察山川形势、地貌、周边环境的传统风水方法。'],['理气派','使用方位、历法、阴阳五行等概念展开术数推演的流派总称。'],['二十四山','将360°等分为24个方位，每个方位宽15°。'],['来龙','传统堪舆中指山脉地势延展方向等脉络概念。'],['龙穴砂水向','传统形势观察中的五类基础术语。'],['立极','在建筑或地块中确立用于分宫的参考中心。'],['坐山','在特定立向定义下，与朝向大致相反的后方方位。'],['朝向','用于描述建筑面向的方位，必须说明测量口径。'],['真北','指向地理北极的方向，与磁北存在磁偏角。'],['磁北','地磁场在当地的磁北方向，易受附近干扰。'],['九宫','将平面划分为3×3的宫位体系。'],['洛书','传统九宫数字图式，常见布局4-9-2/3-5-7/8-1-6。'],['九星','玄空体系常用九个数字及其星名的象征体系。'],['三元九运','常见传统术数将时间划分为九个20年运的体系。'],['运盘','玄空宅盘中描述运星在九宫分布的一层盘。'],['山盘','传统玄空宅盘中与坐山有关的星盘。'],['向盘','传统玄空宅盘中与朝向有关的星盘。'],['流年飞星','以年度条件推导九宫中传统星数的术数方法。'],['排龙诀','以某些玄空传承中的来龙和方位关系推排星位的规则。'],['飞布','依照特定顺序在九宫内递推星数。'],['双山','指两个相邻的山位；具体使用方式依流派而异。'],['巽宫','后天八卦东南方位对应的宫。'],['坎宫','后天八卦正北方位对应的宫。'],['合十','某些玄空格局分析出现的相加为十的数理关系。'],['上南下北','传统九宫图常见方向表达方式，和现代地图不同。'],['证据等级','把现场测量、可靠文献、演示假设、术数判断分别标记。']];
