const storageKey='xingli_school_v1';
let saved={done:[],notes:{},lastLesson:0,quizBest:0};
try{const s=JSON.parse(localStorage.getItem(storageKey)||'null');if(s&&typeof s==='object'){saved={...saved,...s};if(!Array.isArray(saved.done))saved.done=[];}}catch(e){}
let state={view:'home',lesson:Math.max(0,Math.min(35,Number(saved.lastLesson)||0)),module:Math.floor((Number(saved.lastLesson)||0)/6),angle:186,year:2026,palace:'c',caseFilter:'all',caseId:null,quizIndex:0,quizSelected:null,quizSubmitted:false,quizCorrect:0,quizAnswers:[],quizFinished:false};
const $=id=>document.getElementById(id);
const wrap9=n=>((n-1)%9+9)%9+1;
const modulo360=n=>((Number(n)%360)+360)%360;
const mountainAt=a=>Math.floor((modulo360(a)+7.5)/15)%24;
const minIndex=i=>('0'+(i+1)).slice(-2);
function htmlEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function mountainInfo(deg){const a=modulo360(deg),i=mountainAt(a),mid=i*15,min=modulo360(mid-7.5),max=modulo360(mid+7.5),group=mountainGroups[Math.floor(modulo360(a+22.5)/45)%8];return {a,i,m:mountainNames[i],mid,min,max,group,opposite:mountainNames[(i+12)%24]};}
function fmt(n){return Number(n).toFixed(1).replace(/\.0$/,'');}
function toast(msg){const e=$('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2200)}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(saved))}catch(e){}}
function updateProgress(){const count=saved.done.length,p=Math.round(count/36*100);$('sidebar-progress-number').textContent=p+'%';$('sidebar-progress-fill').style.width=p+'%';$('sidebar-progress-text').textContent=`已完成 ${count} / 36 课`}
function navigate(view,opts={}){if(!['home','courses','compass','stars','cases','quiz','resources'].includes(view))return;state.view=view;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));document.querySelectorAll('.nav-item').forEach(x=>{x.classList.toggle('active',x.dataset.view===view)});const title={home:'学习总览',courses:'系统课程',compass:'二十四山罗盘',stars:'九宫飞星实验室',cases:'实景案例研习',quiz:'知识测验',resources:'术语与文献'};$('top-current').textContent=title[view];$('sidebar').classList.remove('open');if(!opts.noScroll)window.scrollTo({top:0,behavior:'instant'});if(view==='home')renderHome();else if(view==='courses')renderCourses();else if(view==='compass')renderCompass();else if(view==='stars')renderStars();else if(view==='cases')renderCases();else if(view==='quiz')renderQuiz();else renderResources();}
function heading(eng,title,sub,more=''){return `<div class="page-intro"><div class="eyebrow">${eng}</div><div class="heading-row"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${more}</div></div>`}
function heroArt(){return `<svg viewBox="0 0 540 365" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="hill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8ea99b" stop-opacity=".6"/><stop offset="1" stop-color="#dce8d9" stop-opacity=".1"/></linearGradient></defs><circle cx="305" cy="189" r="150" fill="none" stroke="#73968a" opacity=".27"/><circle cx="305" cy="189" r="120" fill="none" stroke="#73968a" opacity=".23"/><circle cx="305" cy="189" r="90" fill="none" stroke="#73968a" opacity=".21"/><circle cx="305" cy="189" r="57" fill="none" stroke="#73968a" opacity=".21"/><g transform="translate(305 189)" stroke="#8aa99a" opacity=".52">${Array.from({length:24},(_,i)=>{const a=i*15*Math.PI/180;return `<line x1="${Math.sin(a)*126}" y1="${-Math.cos(a)*126}" x2="${Math.sin(a)*148}" y2="${-Math.cos(a)*148}"/>`}).join('')}</g><path d="M0 281Q52 232 90 244Q140 166 181 199Q229 130 272 185Q319 92 363 152Q405 117 448 177Q488 129 550 190V365H0Z" fill="url(#hill)"/><path d="M0 324Q83 257 152 300Q202 238 266 280Q329 219 386 286Q448 245 550 296V365H0Z" fill="#d1e1d4"/><path d="M95 356Q184 318 258 339T510 334" fill="none" stroke="#86ac9a" opacity=".8" stroke-width="1.5"/><g fill="#426e5a" font-family="serif"><text x="296" y="61" font-size="17">南</text><text x="296" y="323" font-size="17">北</text><text x="170" y="196" font-size="16">东</text><text x="422" y="196" font-size="16">西</text><text x="295" y="200" text-anchor="middle" font-size="35" opacity=".25">山</text></g></svg>`}
function renderHome(){const done=saved.done.length;const next=lessons[state.lesson]||lessons[0];$('view-home').innerHTML=`<div class="hero"><div class="hero-content"><div class="eyebrow">THE ART OF CHINESE GEOMANCY</div><h1>识山川之形<br><em>研方位之理</em></h1><p>一套从零开始的传统风水文化研修课程。以清晰的知识体系、可操作的罗盘工具和有来源的真实建筑案例，循序渐进走向深入理解。</p><div class="hero-actions"><button class="btn btn-primary" data-go="courses" data-lesson="${state.lesson}">${done?'继续第 '+(state.lesson+1)+' 课':'开始系统学习'} <span>↗</span></button><button class="btn btn-outline" data-go="cases">浏览真实案例　→</button></div></div><div class="hero-art">${heroArt()}</div><span class="hero-corner">FORM · DIRECTION · CONTEXT</span></div><div class="stats-grid"><div class="stat card"><div class="stat-symbol">册</div><div><strong>36</strong><small>体系课程 · 六个阶段</small></div></div><div class="stat card"><div class="stat-symbol">景</div><div><strong>07</strong><small>真实案例与模拟练习</small></div></div><div class="stat card"><div class="stat-symbol">盘</div><div><strong>02</strong><small>互动推演实验室</small></div></div><div class="stat card"><div class="stat-symbol">${done?done:'0'}</div><div><strong>${Math.round(done/36*100)}%</strong><small>当前课程完成度</small></div></div></div><div class="section-heading"><h2>六阶研修路径</h2><small>从方位基础逐步学习到玄空与排龙</small></div><div class="home-columns"><div class="stage-timeline">${stages.map((s,i)=>`<div class="stage-tile card" role="button" tabindex="0" data-stage="${i}"><div class="stage-index">STAGE ${minIndex(i)}</div><h3>${s.name}</h3><p>${s.sub}</p><div class="stage-footer"><span>${saved.done.filter(x=>x>=i*6&&x<(i+1)*6).length} / 6 节</span><span>↗</span></div></div>`).join('')}</div><div><div class="quote-card"><div class="eyebrow">A NOTE ON METHOD</div><h3>看得见的环境<br>推得出的规则</h3><p>尊重传统文献，也保留证据边界。每一份案例都注明哪些属于史料事实、哪些属于教学推演。</p></div><div class="method-list"><div class="method-row"><div class="method-n">1</div><div><strong>先学方位，再学口诀</strong><small>从二十四山与罗盘测向开始。</small></div></div><div class="method-row"><div class="method-n">2</div><div><strong>学习可复现的推算</strong><small>九宫和顺逆飞布提供即时反馈。</small></div></div><div class="method-row"><div class="method-n">3</div><div><strong>用真实建筑检验观察能力</strong><small>来源明确，实测缺失处保持标记。</small></div></div></div></div></div><div class="section-heading"><h2>精选研习案例</h2><button class="btn btn-small btn-outline" data-go="cases">查看全部案例 →</button></div><div class="case-grid">${cases.slice(0,2).map(c=>caseTile(c)).join('')}</div>`}
function lessonStatus(i){return saved.done.includes(i)}
function renderCourses(){const i=state.lesson,lesson=lessons[i],module=Math.floor(i/6);state.module=module;const [title,summary,body,conceptStr,stepStr,q,a]=lesson;const concepts=conceptStr.split('|'),steps=stepStr.split('|');const originalFigure=i===28?'<figure class="lesson-figure"><img src="data:image/png;base64," alt="排龙诀参考图（来源待考），包含二十四山、射线、九星吉凶与旺山吉向说明"><figcaption>原始研习材料：排龙诀参考示意图（来源待考）。用于逐层辨认图面结构，完整起算规则尚待核对。</figcaption></figure>':'';$('view-courses').innerHTML=heading('STRUCTURED LEARNING','系统课程','36节循序渐进的教学内容。每节课均包含独立讲解、操作练习、答案与学习笔记。',`<span class="tag warm">当前第 ${i+1} / 36 课</span>`)+`<div class="course-layout"><aside class="course-index card"><h3>全部课程 <span style="float:right;color:#99a79a;font-size:11px">${saved.done.length}/36 已完成</span></h3>${stages.map((s,si)=>`<div><button class="module-toggle" data-toggle-module="${si}"><span style="font-size:13px;color:#495e4e;font-weight:750">${si+1}. ${s.name}</span><span>${state.module===si?'收起':'展开'} ⌄</span></button><div class="module-lessons ${state.module===si?'':'hidden'}">${lessons.slice(si*6,si*6+6).map((l,j)=>{let li=si*6+j;return `<button class="lesson-row ${li===i?'selected':''} ${lessonStatus(li)?'completed':''}" data-lesson-select="${li}"><span class="lesson-num">${minIndex(li)}</span><span class="lesson-title">${l[0]}</span><span class="done-dot">${lessonStatus(li)?'✓':'○'}</span></button>`}).join('')}</div></div>`).join('')}</aside><article class="reading-panel card"><div class="reading-top"><span class="tag">${stages[module].name} · 第 ${i+1} 课</span><span class="tag ${lessonStatus(i)?'green':'gray'}">${lessonStatus(i)?'✓ 已学完':'○ 待学习'}</span></div><h2 class="reading-title">${title}</h2><p class="reading-deck">${summary}</p><div class="reading-meta"><span>◷ 约 12 分钟</span><span>◈ ${stages[module].name}</span><span>✎ 含练习与答案</span></div><div class="reading-body"><h3 class="block-title">本课讲解</h3><p>${body}</p>${originalFigure}<h3 class="block-title">核心概念</h3><div class="concept-pills">${concepts.map(x=>`<span>${x}</span>`).join('')}</div><h3 class="block-title">循序操作</h3><ol class="study-steps">${steps.map(x=>`<li>${x}</li>`).join('')}</ol><h3 class="block-title">课堂检验</h3><div class="exercise-box"><div class="small-label">PRACTICE · 练习 ${minIndex(i)}</div><p>${q}</p><button class="btn btn-small btn-outline" id="show-answer">查看参考答案 ⌄</button><div class="answer" id="lesson-answer">${a}</div></div><h3 class="block-title">我的学习笔记</h3><textarea id="lesson-note" class="reading-note" placeholder="记录知识点、自己的推演和仍有疑问的地方，内容仅存储在本浏览器...">${htmlEscape(saved.notes[i]||'')}</textarea><p class="hint-text">学习笔记自动保存在当前浏览器。清除浏览器站点数据可能会使记录丢失。</p></div><div class="reader-footer"><button class="btn ${lessonStatus(i)?'btn-soft':'btn-primary'}" id="mark-done">${lessonStatus(i)?'✓ 已完成 · 点击取消':'完成本课 ✓'}</button><div class="nav-buttons"><button class="btn btn-small btn-outline" data-prev-lesson ${i===0?'disabled':''}>← 上一课</button><button class="btn btn-small btn-primary" data-next-lesson ${i===35?'disabled':''}>下一课 →</button></div></div></article></div>`}
function svgCompass(angle){const selected=mountainAt(angle);const cx=250,cy=250,inner=110,outer=205;const pos=(a,r)=>[cx+Math.sin(a*Math.PI/180)*r,cy-Math.cos(a*Math.PI/180)*r];const sectors=mountainNames.map((m,i)=>{const start=i*15-7.5,end=i*15+7.5,[x1,y1]=pos(start,outer),[x2,y2]=pos(end,outer),[u1,v1]=pos(start,inner),[u2,v2]=pos(end,inner),[tx,ty]=pos(i*15,156);return `<path class="compass-sector" data-angle="${i*15}" d="M${x1} ${y1} A${outer} ${outer} 0 0 1 ${x2} ${y2} L${u2} ${v2} A${inner} ${inner} 0 0 0 ${u1} ${v1}Z" fill="${i===selected?'#4f8d73':i%3===0?'#f0f1e9':'#faf9f4'}"/><text x="${tx}" y="${ty+5}" text-anchor="middle" font-size="15" font-weight="${selected===i?'700':'500'}" fill="${selected===i?'white':'#536c5b'}">${m}</text>`}).join('');const [ex,ey]=pos(angle,222);return `<svg viewBox="0 0 500 500" class="compass-svg" role="img" aria-label="可交互二十四山罗盘，当前朝向${fmt(angle)}度"><circle cx="250" cy="250" r="226" fill="#f8faf5" stroke="#bfd3be" stroke-width="1.4"/><circle cx="250" cy="250" r="214" fill="none" stroke="#d5e2d5" stroke-dasharray="2 6"/>${sectors}<circle cx="250" cy="250" r="110" fill="#f9f8f0" stroke="#c7dac7" stroke-width="1.3"/><g font-size="18" font-family="serif" fill="#557460"><text x="250" y="20" text-anchor="middle">北 · 0°</text><text x="250" y="489" text-anchor="middle">南 · 180°</text><text x="17" y="256" text-anchor="middle">西</text><text x="486" y="256" text-anchor="middle">东</text></g><line x1="250" y1="250" x2="${ex}" y2="${ey}" stroke="#b4684c" stroke-width="3.5" stroke-linecap="round"/><circle cx="${ex}" cy="${ey}" r="5" fill="#b4684c"/><circle cx="250" cy="250" r="9" fill="#3d7664" stroke="white" stroke-width="4"/><text x="250" y="235" text-anchor="middle" font-family="serif" font-size="13" fill="#9daa9c">当前朝向</text><text x="250" y="273" text-anchor="middle" font-family="Georgia" font-size="34" font-weight="bold" fill="#275f4f">${fmt(angle)}°</text><text x="250" y="296" text-anchor="middle" font-size="12" fill="#7a8b7e">点击山位可切换</text></svg>`}
function renderCompass(){const m=mountainInfo(state.angle);$('view-compass').innerHTML=heading('24 MOUNTAIN COMPASS','二十四山交互罗盘','拖动角度滑块，或直接点击罗盘上的山位，实时换算传统二十四山。本站采用现代北上、北为0°、顺时针增加的标度。')+`<div class="interactive-grid"><div class="lab-card card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div><h3>方位实验室</h3><div class="small-desc">点击扇区或输入朝向度数</div></div><span class="tag green">可交互</span></div><div class="compass-area" id="compass-svg-wrap">${svgCompass(state.angle)}</div><label class="form-label" for="compass-range">建筑朝向角度（°）</label><div class="slider-row"><input id="compass-range" type="range" min="0" max="359" value="${state.angle}" step="0.5"><input class="deg-input" id="compass-number" type="number" min="0" max="359.99" step="0.5" value="${state.angle}" aria-label="朝向度数"><span style="color:#7d9282">°</span></div><div style="display:flex;gap:9px;margin-top:18px;flex-wrap:wrap"><button class="btn btn-small btn-outline" data-set-angle="0">正北 0°</button><button class="btn btn-small btn-outline" data-set-angle="90">正东 90°</button><button class="btn btn-small btn-outline" data-set-angle="180">正南 180°</button><button class="btn btn-small btn-outline" data-set-angle="270">正西 270°</button></div></div><div class="lab-card card"><h3>实时方位解读</h3><p class="small-desc">由数学区间计算得到的客观方向信息</p><div class="result-highlight" id="compass-result"></div><div class="definition-grid" id="compass-defs"></div><div class="lab-subheading">测量时的三项提醒</div><ol class="mini-guide"><li>明确方位角是以真北还是磁北为基准。</li><li>远离强磁场、钢结构和大型电子设备。</li><li>临近山位分界时记录重复测量与误差。</li></ol><div class="notice">本罗盘用于教学换算，不读取设备传感器，也不自动确定建筑坐向或传统吉凶。</div><button class="btn btn-outline" data-go="courses" data-lesson="4">学习第05课：二十四山 →</button></div></div>`;updateCompassInfo()}
function updateCompassInfo(){const m=mountainInfo(state.angle);const a=$('compass-result');if(!a)return;a.innerHTML=`<small>当前朝向判定</small><div class="big-value">${m.m}山 <span style="font:18px -apple-system,'PingFang SC',sans-serif">· ${m.group}方</span></div><p>${fmt(m.a)}° 位于 ${m.m}山覆盖的 ${fmt(m.min)}° 至 ${fmt(m.max)}° 区间${m.min>m.max?'（跨越0°）':''}。</p>`;$('compass-defs').innerHTML=`<div><small>朝向中心角</small><strong>${fmt(m.mid)}°</strong></div><div><small>大致相对坐山</small><strong>${m.opposite}山</strong></div><div><small>每山宽度</small><strong>15°</strong></div><div><small>现代罗盘方位</small><strong>${m.group}</strong></div>`;const c=$('compass-svg-wrap');if(c)c.innerHTML=svgCompass(state.angle);const r=$('compass-range'),n=$('compass-number');if(r)r.value=state.angle;if(n&&document.activeElement!==n)n.value=state.angle;}
function setAngle(a){if(a===''||!Number.isFinite(Number(a)))return;state.angle=Math.round(modulo360(Number(a))*100)/100;updateCompassInfo()}
function starFor(year,base){let center=wrap9(3-(year-2024));return wrap9(center+(base-5))}
function renderStars(){const year=state.year,p=palaces.find(x=>x.key===state.palace)||palaces[4],v=starFor(year,p.base);$('view-stars').innerHTML=heading('FLYING STAR LABORATORY','九宫飞星实验室','以洛书九宫为基础的流年飞星教学演示。点击宫位可查看数字与星名，切换年份观察星数如何循环变化。')+`<div class="interactive-grid"><div class="lab-card card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:start"><div><h3>九宫年度星盘</h3><div class="small-desc">上南下北，传统九宫图示方向</div></div><span class="tag green">动态推算</span></div><div class="star-selector"><label class="form-label" for="star-year" style="margin:0">选择演示年份</label><select id="star-year">${Array.from({length:20},(_,i)=>2024+i).map(y=>`<option value="${y}" ${year===y?'selected':''}>${y} 年</option>`).join('')}</select></div><div class="orientation-note">↑ 南 （传统图面） ↑</div><div class="star-board">${palaces.map(p=>`<button class="star-cell ${state.palace===p.key?'active':''}" data-palace="${p.key}"><span class="palace">${p.name} · ${p.dir}</span><span class="star-value">${starFor(year,p.base)}</span><span class="star-name">${starNames[starFor(year,p.base)]}</span></button>`).join('')}</div><div class="orientation-note">↓ 北 ↓</div><div class="hint-text" style="margin-top:17px">数字按中宫→乾→兑→艮→离→坎→坤→震→巽的洛书顺飞顺序循环赋值。</div></div><div class="lab-card card"><h3>${year} 年 · 九宫解读</h3><p class="small-desc">按常见流年飞星的简化年度计算示例</p><div class="result-highlight"><small>年度中宫</small><div class="big-value">${starFor(year,5)} <span style="font:16px -apple-system,'PingFang SC',sans-serif">${starNames[starFor(year,5)]}</span></div><p>本示例以2024年中宫3为起点，每年中宫数递减1，经过1回到9。</p></div><div class="star-explain"><strong>${p.name}（${p.dir}） · ${v} ${starNames[v]}</strong><div style="margin-top:9px">此宫位在${year}年对应教学星数 ${v}。请先掌握数字与宫位的可复算关系，传统吉凶象义需结合特定流派及具体语境讨论。</div></div><div class="lab-subheading">与住宅宅盘有什么区别？</div><p class="small-desc">此图只演示年度九宫数字，未纳入建筑坐向、建成年代及山星、向星等要素，不能作为完整住宅玄空宅盘。</p><div class="notice">简化说明：本站按公历年份切换，未处理立春节气前后分界；正式研读需遵循所用教材的历法规则。</div><button class="btn btn-outline" data-go="courses" data-lesson="22">学习第23课：流年飞星 →</button></div></div>`}
function caseIllustration(kind){const frame=`<rect width="800" height="340" fill="#e1e9df"/><path d="M0 270 Q130 220 245 255T510 235T800 260V340H0Z" fill="#bfd3bf" opacity=".6"/><path d="M0 300 Q210 270 400 293T800 279" stroke="#f9faf2" stroke-width="3" fill="none" opacity=".55"/>`;
let subject='';
if(kind==='water')subject=`<path d="M0 154 Q90 115 179 142T352 141T550 120T800 151" stroke="#a4c8c0" stroke-width="30" fill="none" opacity=".7"/><ellipse cx="418" cy="184" rx="115" ry="55" fill="#91bdba"/><ellipse cx="418" cy="184" rx="88" ry="36" fill="#b9d8d0"/><path d="M418 239Q400 272 485 308" stroke="#7daeb1" stroke-width="20" fill="none"/><g fill="#f9f8f0" stroke="#849b89" stroke-width="2">${Array.from({length:18},(_,i)=>{let x=105+(i%6)*103,y=90+Math.floor(i/6)*73+(i%3)*12;return `<path d="M${x} ${y+22}v-18l22-16 23 16v18z"/><path d="M${x-5} ${y+5}l27-24 29 24" fill="none"/>`}).join('')}</g>`;
if(kind==='axis')subject=`<path d="M395 0V340" stroke="#d6b99e" stroke-width="60" opacity=".6"/><path d="M395 0V340" stroke="#fffdf6" stroke-width="3" stroke-dasharray="8 16" opacity=".8"/>${[48,122,205,290].map((y,i)=>`<g transform="translate(0 ${y})"><rect x="${i===2?328:345}" y="0" width="${i===2?134:100}" height="37" fill="#d6ac88" stroke="#fff5e8" stroke-width="3" rx="2"/><path d="M${i===2?316:336} 3l${i===2?79:60}-20 ${i===2?79:60} 20" fill="#9e766a" stroke="#8f695e" stroke-width="2"/></g>`).join('')}<path d="M110 110q110-75 190-30M500 150q100-50 210-22" fill="none" stroke="#739b83" stroke-width="10" opacity=".4"/>`;
if(kind==='tulou')subject=`<ellipse cx="410" cy="207" rx="220" ry="108" fill="#bca284" stroke="#eee9d9" stroke-width="11"/><ellipse cx="410" cy="207" rx="163" ry="70" fill="#7c9c85" stroke="#f3e9d1" stroke-width="10"/><ellipse cx="410" cy="207" rx="120" ry="48" fill="#b2c8ae"/><path d="M405 308v-45" stroke="#faf6e7" stroke-width="21"/><path d="M403 275v-38" stroke="#6f8e79" stroke-width="12"/>${Array.from({length:30},(_,i)=>{let a=i*Math.PI*2/30,x=410+191*Math.cos(a),y=207+87*Math.sin(a);return `<circle cx="${x}" cy="${y}" r="3" fill="#faf3e3" opacity=".75"/>`}).join('')}`;
if(kind==='garden')subject=`<path d="M75 77h650v190H75Z" fill="#c4d2bc" stroke="#9eb19d" stroke-width="7"/><path d="M100 115Q189 145 281 108T466 116T698 115" stroke="#eff4e8" stroke-width="10" fill="none"/><path d="M231 156Q280 119 372 157Q457 197 525 160Q588 184 574 232Q489 273 402 240Q321 283 251 236Z" fill="#8db8b2" stroke="#b5d8cb" stroke-width="5"/><g fill="#637d66">${[[135,180],[185,211],[622,154],[660,200],[319,130]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="28"/><circle cx="${x+10}" cy="${y-10}" r="21" fill="#7e9e83"/>`).join('')}</g><path d="M474 79v47h92V79z" fill="#f8f4e7" stroke="#b6a990" stroke-width="4"/><path d="M460 83l60-35 60 35" fill="#a38c78"/>`;
if(kind==='flat'||kind==='office')subject=`<rect x="223" y="55" width="355" height="230" rx="3" fill="#f7f7f0" stroke="#91a98e" stroke-width="8"/><path d="M222 154h355M379 55v229M453 154v130" stroke="#8da58e" stroke-width="7"/><rect x="370" y="278" width="70" height="14" fill="#adcfcc"/><rect x="254" y="82" width="83" height="49" fill="#dae5d9"/><rect x="482" y="188" width="58" height="57" fill="#dae5d9"/><path d="M400 263v-89" stroke="#ae7960" stroke-width="5"/><path d="M387 191l13-20 13 20" fill="none" stroke="#ae7960" stroke-width="5"/>`;
if(kind==='courtyard')subject=`<rect x="210" y="52" width="380" height="236" rx="4" fill="#c3d3bf" stroke="#96a991" stroke-width="9"/><rect x="229" y="68" width="342" height="50" fill="#f4f0df" stroke="#a99b80" stroke-width="4"/><rect x="229" y="225" width="342" height="45" fill="#f4f0df" stroke="#a99b80" stroke-width="4"/><rect x="228" y="122" width="64" height="99" fill="#f4f0df" stroke="#a99b80" stroke-width="4"/><rect x="508" y="122" width="64" height="99" fill="#f4f0df" stroke="#a99b80" stroke-width="4"/><circle cx="399" cy="173" r="35" fill="#a2c6a3"/><path d="M391 288v-47" stroke="#b17b63" stroke-width="6"/>`;
return `<svg viewBox="0 0 800 340" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${{water:'宏村水系统抽象示意图',axis:'北京中轴线抽象示意图',tulou:'福建土楼典型形制示意图',garden:'苏州园林景观构成示意图',flat:'模拟住宅户型示意图',office:'模拟办公楼示意图',courtyard:'模拟合院示意图'}[kind]}">${frame}${subject}<rect x="0" y="0" width="800" height="340" fill="url(#fade-${kind})" opacity=".12"/><defs><linearGradient id="fade-${kind}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#2d5947"/></linearGradient></defs></svg>`}
function caseTile(c){return `<div class="card case-tile" role="button" tabindex="0" data-case="${c.id}"><div class="case-graphic">${caseIllustration(c.kind)}<span class="case-type">${c.type==='real'?'真实建筑 · 有来源':'教学模拟 · 假设数据'}</span></div><div class="case-info"><div class="case-meta">${c.location} · ${c.period}</div><h3>${c.title}</h3><p>${c.summary}</p><div class="case-open"><span>进入完整案例</span><span>↗</span></div></div></div>`}
function renderCases(){let list=cases.filter(c=>state.caseFilter==='all'||c.type===state.caseFilter);if(state.caseId){const c=cases.find(c=>c.id===state.caseId);if(c){renderCaseDetail(c);return}}$('view-cases').innerHTML=heading('CASE STUDY ARCHIVE','实景案例研习','4个有官方资料支持的真实建筑与聚落案例，外加3个用于罗盘、测向及现场记录的模拟案例。真实案例中的示意插画仅表达空间概念。')+`<div class="case-controls"><button class="chip ${state.caseFilter==='all'?'active':''}" data-case-filter="all">全部案例 · 7</button><button class="chip ${state.caseFilter==='real'?'active':''}" data-case-filter="real">世界遗产真实案例 · 4</button><button class="chip ${state.caseFilter==='sim'?'active':''}" data-case-filter="sim">实操模拟 · 3</button></div><div class="case-grid">${list.map(caseTile).join('')}</div><div class="notice">案例核查原则：遗产背景与历史形态参照 UNESCO 资料；传统风水观念只作文化解读。未提供实地罗盘测量的项目不虚构坐向，也不生成真实建筑的吉凶结论。</div>`}
function renderCaseDetail(c){const source=c.source!==null?sources[c.source]:null;$('view-cases').innerHTML=`<div class="case-detail card"><button class="back-link" data-back-cases>← 返回案例馆</button><div class="detail-image">${caseIllustration(c.kind)}</div><div class="detail-header"><div class="eyebrow">${c.type==='real'?'DOCUMENTED HERITAGE CASE':'INTERACTIVE TRAINING CASE'}</div><h2>${c.title}</h2><p>${c.location}　·　${c.period}</p></div><div class="detail-columns"><div class="detail-panel"><h4>01 · 可核实事实 / 假设条件</h4><ul>${c.facts.map(f=>`<li>${f}</li>`).join('')}</ul></div><div class="detail-panel"><h4>02 · 建议研习路线</h4><ul>${c.analysis.map(a=>`<li>${a}</li>`).join('')}</ul></div></div><div class="detail-panel" style="margin-top:15px"><h4>03 · 本案例的证据边界</h4><p style="margin:0">${c.limits}</p></div><div class="exercise-box" style="margin-top:15px"><div class="small-label">CASE ASSIGNMENT</div><p>${c.question}</p></div>${source?`<div class="case-citation">资料来源：<strong>${source.org}</strong>。${source.desc}<br><a href="${source.url}" target="_blank" rel="noopener noreferrer">访问权威原始资料 ↗</a></div>`:`<div class="notice">此案例使用模拟输入，供方法练习使用。可通过下方记录单自行输入测向数据并导出本地记录。</div>${fieldForm(c)}`}</div>`}
function fieldForm(c){return `<div class="detail-panel" style="margin-top:16px"><h4>04 · 实操记录单（本地填写）</h4><div class="field-form"><label>案例名称<input id="field-title" type="text" value="${c.title}"></label><label>测量日期<input id="field-date" type="text" value="${new Date().toLocaleDateString('zh-CN')}"></label><label>测得朝向（度）<input id="field-angle" type="number" min="0" max="359.99" step="0.1" value="${c.angle}"></label><label>参照方向<select id="field-north"><option>真北</option><option>磁北</option><option>尚未确定</option></select></label><label class="full">现场观察与备注<textarea id="field-notes" rows="4" placeholder="记录测量点、建筑周边道路、采光、噪声、地形、水体等。"></textarea></label></div><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:15px"><button class="btn btn-primary" id="export-field">生成并导出记录（TXT） ↗</button><span id="field-mountain" class="tag">当前为 ${mountainInfo(c.angle).m}山</span></div><p class="hint-text" style="margin-top:12px">导出的记录包含测量条件和“教学模拟”声明。本站不保存这张表单到服务器。</p></div>`}
function downloadField(){let c=cases.find(x=>x.id===state.caseId);if(!c)return;let title=$('field-title').value,angle=Number($('field-angle').value);if(!Number.isFinite(angle)||angle<0||angle>=360){toast('请输入0°至359.99°的有效角度');return}let m=mountainInfo(angle),date=$('field-date').value,north=$('field-north').value,notes=$('field-notes').value;let content=`形理书院｜现场记录单（教学模拟）\n---------------------------------\n案例：${title}\n记录日期：${date}\n方位基准：${north}\n朝向：${fmt(angle)}°\n二十四山区间：${m.m}山，${fmt(m.min)}°至${fmt(m.max)}°\n相对坐山：${m.opposite}山\n现场观察：\n${notes||'（未填写）'}\n\n数据说明：本案例原始设定为教学假设。换算为角度区间计算，不包含完整宅盘、排龙吉凶，也不能用于替代建筑测绘和安全评估。\n`;const blob=new Blob(['\ufeff',content],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='形理书院_实操记录_'+new Date().toISOString().slice(0,10)+'.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('记录单已导出')}
function renderQuiz(){if(state.quizFinished){let score=state.quizCorrect;let total=quizBank.length;saved.quizBest=Math.max(saved.quizBest,score);persist();$('view-quiz').innerHTML=heading('KNOWLEDGE REVIEW','知识测验','检查是否真正掌握基本方位、九宫数字、历史案例和研究边界。')+`<div class="card quiz-panel" style="max-width:700px;text-align:center;margin:auto"><div class="eyebrow" style="justify-content:center">YOUR RESULT</div><h2 style="font:700 32px 'Songti SC',serif;margin:22px 0 6px">本轮测验已完成</h2><div class="quiz-score">${score}<span style="font-size:18px;color:#9aa99d"> / ${total}</span></div><p class="subtitle" style="margin:10px auto 25px">${score===total?'全部回答正确。可以继续进阶研习。':score>=9?'基础掌握较好，建议复核答错的问题。':'建议继续阅读课程并结合罗盘实验练习。'}</p><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap"><button class="btn btn-primary" id="restart-quiz">再测一次</button><button class="btn btn-outline" data-go="courses">返回课程 →</button></div><h3 style="text-align:left;margin-top:32px">本轮答题复盘</h3>${quizBank.map((x,i)=>`<div style="padding:13px 0;border-bottom:1px solid #eee;text-align:left"><strong style="color:${state.quizAnswers[i]===x.a?'#408467':'#ad7863'}">${state.quizAnswers[i]===x.a?'✓':'✕'}　${x.q}</strong><p style="font-size:12px;color:#8b958a;margin:5px 0">正确答案：${x.options[x.a]}。${x.why}</p></div>`).join('')}</div>`;return}
const q=quizBank[state.quizIndex],sel=state.quizSelected,done=state.quizSubmitted;let count=state.quizIndex+1;
$('view-quiz').innerHTML=heading('KNOWLEDGE REVIEW','知识测验','12道题覆盖方向、数字、传统文化及证据方法，完成后自动生成错题回顾。')+`<div class="quiz-grid"><div class="quiz-panel card"><div class="quiz-progress"><span>第 ${count} / ${quizBank.length} 题</span><span>当前答对 ${state.quizCorrect} 题</span></div><div class="track" style="height:5px"><div class="track-fill" style="width:${(count-1)/quizBank.length*100}%"></div></div><h2 class="quiz-question">${q.q}</h2>${q.options.map((op,i)=>`<button class="quiz-choice ${sel===i?'sel':''} ${done&&i===q.a?'correct':''} ${done&&sel===i&&sel!==q.a?'wrong':''}" data-answer-choice="${i}" ${done?'disabled':''}><span class="choice-letter">${'ABCD'[i]}</span>${op}</button>`).join('')}${done?`<div class="quiz-feedback"><b>${sel===q.a?'回答正确。':'本题需要复习。'}</b> ${q.why}</div>`:''}<div class="quiz-actions"><span class="hint-text">${done?'阅读解析后继续':'选择一个答案后提交'}</span><button class="btn btn-primary" id="quiz-next" ${sel===null?'disabled':''}>${done?(count===quizBank.length?'查看测验结果':'下一题 →'):'提交答案'}</button></div></div><div class="quiz-sidebar card"><div class="eyebrow">LEARNING CHECKPOINT</div><h3 style="font:24px 'Songti SC',serif;margin:18px 0">以题促学</h3><p class="quiz-intro-text">每一题都对应课程中的一个可验证知识点。传统术数内容以内部规则为考核对象，不将吉凶判断作为事实题。</p><div class="result-highlight"><small>历史最好成绩</small><div class="big-value">${saved.quizBest} <span style="font:14px sans-serif">/ 12</span></div></div><div class="lab-subheading">建议</div><p class="quiz-intro-text">错题可返回课程复习。尝试在罗盘中输入角度，或切换九宫年份亲自验证。</p><button class="btn btn-outline" data-go="compass">去罗盘实验室 →</button></div></div>`}
function renderResources(){$('view-resources').innerHTML=heading('REFERENCE LIBRARY','术语与文献','快速查阅26个常见术语与七份阅读来源。真实建筑背景以可追溯文献为依据，课程中的术数部分按传统体系处理。')+`<div class="section-heading" style="margin-top:12px"><h2>术语速查</h2><small>${gloss.length} 个术语</small></div><div class="glossary-grid">${gloss.map(([term,desc])=>`<div class="glossary-tile card"><strong>${term}</strong><p>${desc}</p></div>`).join('')}</div><div class="section-heading"><h2>主要参考文献及资料</h2><small>点击可访问原始来源</small></div><div class="source-list">${sources.map(s=>`<div class="source-item card"><div><h4>${s.title}</h4><p>${s.org} · ${s.desc}</p></div><a href="${s.url}" target="_blank" rel="noopener noreferrer">阅读 ↗</a></div>`).join('')}</div><div class="notice">方法说明：本网站是可离线运行的课程演示站，学习进度与笔记仅留在浏览器。引用的世界遗产文献需要联网打开。案例绘图是教学示意，未采用未经许可的卫星影像、精确测绘图或摄影作品。</div>`}
function openSearch(){const el=$('search-modal');el.classList.add('open');el.setAttribute('aria-hidden','false');$('site-search').value='';showSearchResults('');setTimeout(()=>$('site-search').focus(),15)}
function closeSearch(){$('search-modal').classList.remove('open');$('search-modal').setAttribute('aria-hidden','true')}
function searchData(q){let entries=[...lessons.map((x,i)=>({type:'课程',title:`第${minIndex(i)}课 · ${x[0]}`,summary:x[1],target:'course',id:i,search:x.join(' ')})),...cases.map(c=>({type:'案例',title:c.title,summary:c.summary,target:'case',id:c.id,search:[c.title,c.summary,c.location,...c.facts].join(' ')})),...gloss.map(([term,desc])=>({type:'术语',title:term,summary:desc,target:'gloss',id:term,search:term+' '+desc}))];const t=q.trim().toLowerCase();return (t?entries.filter(e=>e.search.toLowerCase().includes(t)):entries.slice(0,7)).slice(0,18)}
function showSearchResults(q){let rows=searchData(q);$('search-results').innerHTML=rows.length?rows.map(r=>`<button class="search-result" data-search-type="${r.target}" data-search-id="${htmlEscape(r.id)}"><span style="color:#65937a">${r.type==='课程'?'▤':r.type==='案例'?'▧':'▣'}</span><span><strong>${htmlEscape(r.title)}</strong><small>${htmlEscape(r.summary.slice(0,62))}${r.summary.length>62?'…':''}</small></span><span class="result-type">${r.type}</span></button>`).join(''):`<div style="padding:24px;color:#9ea79d;text-align:center">没有找到相关条目，试试“罗盘”“宏村”“九星”。</div>`}
function searchGo(type,id){closeSearch();if(type==='course'){state.lesson=Number(id);saved.lastLesson=state.lesson;persist();navigate('courses')}else if(type==='case'){state.caseId=id;navigate('cases')}else navigate('resources')}
function handleClick(e){const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return}const go=e.target.closest('[data-go]');if(go){let name=go.dataset.go;if(go.dataset.lesson!==undefined){state.lesson=Number(go.dataset.lesson);saved.lastLesson=state.lesson;persist()}if(name==='cases')state.caseId=null;navigate(name);return}const st=e.target.closest('[data-stage]');if(st){state.lesson=Number(st.dataset.stage)*6;saved.lastLesson=state.lesson;persist();navigate('courses');return}const sel=e.target.closest('[data-lesson-select]');if(sel){state.lesson=Number(sel.dataset.lessonSelect);saved.lastLesson=state.lesson;persist();renderCourses();return}const toggle=e.target.closest('[data-toggle-module]');if(toggle){let next=Number(toggle.dataset.toggleModule);state.module=state.module===next?-1:next;const blocks=$('view-courses').querySelectorAll('.module-lessons');blocks.forEach((x,i)=>x.classList.toggle('hidden',i!==state.module));$('view-courses').querySelectorAll('.module-toggle').forEach((x,i)=>x.lastElementChild.textContent=(state.module===i?'收起':'展开')+' ⌄');return}if(e.target.closest('#show-answer')){$('lesson-answer').classList.toggle('open');$('show-answer').textContent=$('lesson-answer').classList.contains('open')?'收起参考答案 ⌃':'查看参考答案 ⌄';return}if(e.target.closest('#mark-done')){if(lessonStatus(state.lesson)){saved.done=saved.done.filter(x=>x!==state.lesson);toast('已取消完成标记')}else{saved.done.push(state.lesson);toast('已记录课程完成')}persist();updateProgress();renderCourses();return}if(e.target.closest('[data-next-lesson]')){state.lesson=Math.min(state.lesson+1,35);saved.lastLesson=state.lesson;persist();renderCourses();window.scrollTo({top:0,behavior:'smooth'});return}if(e.target.closest('[data-prev-lesson]')){state.lesson=Math.max(state.lesson-1,0);saved.lastLesson=state.lesson;persist();renderCourses();window.scrollTo({top:0,behavior:'smooth'});return}
const sector=e.target.closest('[data-angle]');if(sector){setAngle(sector.dataset.angle);return}const setangle=e.target.closest('[data-set-angle]');if(setangle){setAngle(setangle.dataset.setAngle);return}const cf=e.target.closest('[data-case-filter]');if(cf){state.caseFilter=cf.dataset.caseFilter;state.caseId=null;renderCases();return}const c=e.target.closest('[data-case]');if(c){state.caseId=c.dataset.case;navigate('cases');return}if(e.target.closest('[data-back-cases]')){state.caseId=null;renderCases();return}const pc=e.target.closest('[data-palace]');if(pc){state.palace=pc.dataset.palace;renderStars();return}if(e.target.closest('#export-field')){downloadField();return}const ans=e.target.closest('[data-answer-choice]');if(ans&&!state.quizSubmitted){state.quizSelected=Number(ans.dataset.answerChoice);renderQuiz();return}if(e.target.closest('#quiz-next')){if(state.quizSelected===null)return;if(!state.quizSubmitted){state.quizSubmitted=true;state.quizAnswers.push(state.quizSelected);if(state.quizSelected===quizBank[state.quizIndex].a)state.quizCorrect++;renderQuiz()}else if(state.quizIndex===quizBank.length-1){state.quizFinished=true;renderQuiz()}else{state.quizIndex++;state.quizSelected=null;state.quizSubmitted=false;renderQuiz()}return}if(e.target.closest('#restart-quiz')){state.quizIndex=0;state.quizSelected=null;state.quizSubmitted=false;state.quizCorrect=0;state.quizAnswers=[];state.quizFinished=false;renderQuiz();return}const sr=e.target.closest('[data-search-type]');if(sr){searchGo(sr.dataset.searchType,sr.dataset.searchId);return}}
function handleInput(e){if(e.target.id==='compass-range'||e.target.id==='compass-number'){setAngle(e.target.value);return}if(e.target.id==='lesson-note'){saved.notes[state.lesson]=e.target.value;persist();return}if(e.target.id==='site-search'){showSearchResults(e.target.value);return}if(e.target.id==='field-angle'){const el=$('field-mountain'),v=Number(e.target.value);if(el)el.textContent=e.target.value!==''&&Number.isFinite(v)&&v>=0&&v<360?`当前为 ${mountainInfo(v).m}山`:'请输入有效角度';return}if(e.target.id==='star-year'){state.year=Number(e.target.value);renderStars();return}}
function init(){document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleInput);$('search-trigger').addEventListener('click',openSearch);$('close-search').addEventListener('click',closeSearch);$('search-modal').addEventListener('click',e=>{if(e.target.id==='search-modal')closeSearch()});$('mobile-menu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeSearch();$('sidebar').classList.remove('open')}if(e.key==='Enter'&&e.target.matches('[data-stage],[data-case],.brand')){e.target.click()}if(e.key==='Enter'&&e.target.id==='site-search'){const row=$('search-results').querySelector('[data-search-type]');if(row)row.click()}});updateProgress();navigate('home',{noScroll:true})}
/* 形理书院 V2 · 课程精讲、高清图解、案例实训与学习考核 */
const advancedLessons = [
 {aim:'能区分环境事实、史料叙述和传统术数判断，并完成一张观察表。', lead:'走进一处老宅，人们可能同时谈到背山面水、屋前采光、某年运势。这些陈述的证据要求并不相同。本课教你先把问题分层。',sections:[
  ['01 · 风水研究涉及什么','传统堪舆涉及建筑选址、村落布局、地形水系、建筑朝向与象征体系。形势观察关心看得见的地貌、山水与建筑关系，理气研究则会结合方位、数字和历法进行传统推演。学习时先固定研究对象，避免一句“风水好”包含多个含义。'],
  ['02 · 学会给信息贴标签','以宏村为例：“村中有月沼”可核对照片和文献；“水系用于村落生活与景观”可以进一步检索历史资料；“某条街能提高财运”缺少可验证证据。学习者应分别注明观察事实、资料记载、传统解释、未经证实的推测。'],
  ['03 · 做一次家庭观察','找一张住宅照片，记录朝向是否可见、窗户所在面、周边是否遮挡、附近道路的位置。看不见的内容填写“待核实”，不要根据照片凭空计算测向角度。最后写一句你愿意继续检验的问题。']],
  example:'某住宅朝向186°，这可以由合适的测量方法验证；“属午山”可通过二十四山的分区规则计算；“住进去就会升职”则没有因果证明。',mistake:'把传统文化研究等同于现代建筑安全评估，或者依据一张网络图片为真实房屋断言结果。',related:'以“照片上能否直接量出朝向”为问题开始，学习如何记录信息来源。', diagram:'terrain'},
 {aim:'记住五行相生循环，理解阴阳和五行是传统分类与象征框架。',lead:'阴阳与五行是后续八卦、九星、传统方位的共同语言。把它当成一套历史概念图，会比背诵“吉凶口诀”更容易理解。',sections:[
  ['01 · 阴阳描述相对关系','阴阳通常用于表达昼夜、动静、明暗等关系。一件事物的“阴”“阳”往往取决于比较对象与语境。白天与夜晚可以构成一组，屋外与屋内又是一组；不要把它们当成两种可测量的特殊能量。'],
  ['02 · 五行相生为何是一个环','按常见顺序，木生火、火生土、土生金、金生水、水生木。这个循环可用于记忆各类传统对应关系。常见相克次序是木克土、土克水、水克火、火克金、金克木。相生和相克在古籍中是模型中的关系。'],
  ['03 · 将象征与现实分离','“水克火”作为历史概念属于五行模型；如果要判断厨房着火概率，应检查线路、燃气、材料、消防条件。区分体系内部推演与现实中的物理因果，是长期研习的重要方法。']],example:'用五张纸分别写木、火、土、金、水，按相生关系围成圆圈。交换任意两张，你就能看到口诀对应关系为什么会被破坏。',mistake:'将“五行中的金”当作元素周期表的一类金属，并用五行克制关系直接预测健康、财运。',related:'先记住相生，再尝试在不看答案的情况下复述相克次序。',diagram:'wuxing'},
 {aim:'辨认八卦及两种常用方位排列，能够独立填写后天八卦的八个方向。',lead:'八卦不是只有一套排法。先天八卦和后天八卦都出现于传统图式中，具体方位关系不同。',sections:[
  ['01 · 卦由三条爻组成','三条不断开的阳爻构成乾，三条断开的阴爻构成坤。其他六卦由两种爻的不同组合组成。可以先观察图中的线条，而不急着理解全部卦义。'],
  ['02 · 先天与后天，分别记忆','常见先天排列为乾南、坤北、离东、坎西、兑东南、震东北、巽西南、艮西北。后天排列为坎北、离南、震东、兑西、艮东北、巽东南、坤西南、乾西北。学习罗盘时通常先掌握后天方位。'],
  ['03 · 看盘时先找方向箭头','传统八卦图可能把南画在上方，现代地图通常把北画在上方。使用不同制图口径时，卦名必须随实际方位调整。练习先把北箭头写出来，防止一整盘方向颠倒。']],example:'当你在北侧查后天八卦，应填入“坎”；在南侧应填“离”。换成先天排列，北侧为“坤”，南侧为“乾”。',mistake:'把先天乾南直接复制到后天罗盘，随后用后天规则继续排盘。',related:'推荐先背“坎北离南、震东兑西”，再补四隅。',diagram:'bagua'},
 {aim:'准确识读十天干、十二地支，并知道它们怎样进入二十四山。',lead:'二十四山的名称中，多数来自天干、地支和四维卦。如果连名称类别都没分清，读罗盘时很容易混淆。',sections:[
  ['01 · 两套独立的顺序','十天干：甲乙丙丁戊己庚辛壬癸。十二地支：子丑寅卯辰巳午未申酉戌亥。记忆时先分开，再结合传统方位。二者也广泛出现在历法、文献、时辰记录中。'],
  ['02 · 二十四山从何组成','二十四山采用八个天干甲乙丙丁庚辛壬癸、十二地支和乾坤艮巽四个卦名，合计24项。戊、己没有列在二十四山序列中。它们的组合方式遵循固定方向次序。'],
  ['03 · 用罗盘建立空间记忆','先定位四正子北、午南、卯东、酉西；随后填入每个四正附近的相邻名称。例如北方三山是壬、子、癸，东方三山是甲、卯、乙。把方位与名称一起记，会比抄十遍名单有效。']],example:'看到“辰巽巳”三个相邻山，分别辨认为地支辰、卦名巽、地支巳，它们共同位于东南方位段。',mistake:'以为全部二十四山都是天干，或者以为“艮”是某个地支。',related:'打开实验罗盘，点击东、南、西、北四组，再逐步补全四隅。',diagram:'stems'},
 {aim:'任意给定一个方位角，都能算出山位和相对坐山，并解释分界点。',lead:'这是整个网站最重要的基础技能。每山宽15°，只要知道从正北起顺时针量角，就能从0°推算全部24个山位。',sections:[
  ['01 · 从正北开始数','现代方位角以北为0°、东为90°、南为180°、西为270°，顺时针增加。子山以0°为中心，其范围从352.5°跨越0°至7.5°。下一山癸以15°为中心，覆盖7.5°至22.5°。'],
  ['02 · 记住公式和边界','把角度换算到0°至360°之间，再加7.5°，整除15°后取余24，得到山的序号。恰好处于边界时，本网站为计算演示采用右侧区间规则。现实测向必须对设备误差作出说明。'],
  ['03 · 朝向与坐山','假设朝向为186°，落入午山172.5°至187.5°。把朝向加180°并对360°取余得到6°，处于子山，所以可表述为“坐子向午”。具体建筑如何取向仍需先明确测点和流派。']],example:'186°→午山；189°→丁山，二者相差仅3°，却跨过187.5°边界。越靠近边界，越要保存重复测量与误差范围。',mistake:'把“朝向186°”错当成“坐山186°”；或者把靠近边界的单次读数当成准确无误的结果。',related:'在罗盘实验室输入186°、189°、352°、359°，逐个验证。',diagram:'mountain'},
 {aim:'能够解释真北与磁北的差别，写出一份包含测量条件的朝向记录。',lead:'一张看似精密的罗盘图，不代表现实测量足够准确。建筑附近的大量金属构件还会影响读数。',sections:[
  ['01 · 方位角的两种“北”','真北是指向地理北极的方向；磁北与当地地磁方向有关。两者之间的角度称磁偏角，其数值与地点、年份有关。学习时应在记录中注明所用基准，不能直接套用固定磁偏角。'],
  ['02 · 测量时的干扰因素','钢门、电梯、车辆、供电设备和附近铁磁物体可能影响电子指南针或磁罗盘的读数。同一建筑不同测点也可能差异明显。记录重复结果、仪器和测量位置很重要。'],
  ['03 · 一条合格的测向记录','例如：2026年10月，模拟住宅南侧外墙，测点A，采用真北基准，三次读数185.7°、186.2°、186.1°，平均186.0°。这仅是演示格式，真实报告还应说明如何获得真北基准。']],example:'如果测得187.4°，距离187.5°边界仅0.1°。在误差可能达到1°的情况下，不能断言它必然落在午山。',mistake:'将手机在门口测一次显示的度数当作最终精确立向，并忽略磁偏角。',related:'尝试在罗盘实验室输入187.4°、187.6°，观察山位变化。',diagram:'north'}
];
