function svgShell(body,label='课程专业图解',view='0 0 960 530') {return `<svg class="edu-diagram" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg" viewBox="${view}"><rect width="960" height="530" rx="22" fill="#f8f8f2"/><g font-family="PingFang SC,Microsoft YaHei,sans-serif">${body}</g></svg>`;}
function labelSvg(x,y,text,sz=19,color='#365b4a',anchor='middle'){return `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${sz}" fill="${color}">${text}</text>`;}
function angleXY(a,r,cx=480,cy=266){let t=a*Math.PI/180;return [cx+Math.sin(t)*r,cy-Math.cos(t)*r];}
function mountainDiagram(){let rings=mountainNames.map((m,i)=>{const ang=i*15;const s=angleXY(ang-7.5,216),e=angleXY(ang+7.5,216),s2=angleXY(ang-7.5,108),e2=angleXY(ang+7.5,108),t=angleXY(ang,167);return `<path d="M${s.join(' ')}A216 216 0 0 1 ${e.join(' ')}L${e2.join(' ')}A108 108 0 0 0 ${s2.join(' ')}Z" fill="${i%3===0?'#e8eee4':'#fffdf8'}" stroke="#aebcae" stroke-width="1"/>${labelSvg(t[0],t[1]+7,m,22)}`}).join('');let ticks=[0,90,180,270].map((a,i)=>{let q=angleXY(a,241);return labelSvg(q[0],q[1]+7,['北 0°','东 90°','南 180°','西 270°'][i],17,'#ae714c')}).join('');return svgShell(`<circle cx="480" cy="266" r="223" fill="#fff" stroke="#6a8c76" stroke-width="3"/>${rings}<circle cx="480" cy="266" r="108" fill="#e9f1e9" stroke="#809c88" stroke-width="2"/>${labelSvg(480,250,'360° ÷ 24',30)}${labelSvg(480,290,'每山 15°',24,'#865f43')}${ticks}${labelSvg(780,92,'数学分区示意',18,'#718575')}`, '24山精细矢量图');}
function baguaDiagram(){let xy=(a,r,cx,cy)=>[cx+Math.sin(a*Math.PI/180)*r,cy-Math.cos(a*Math.PI/180)*r];let sets=[{cx:248,title:'先天八卦',dirs:['坤','震','离','兑','乾','巽','坎','艮'],sub:'常见先天方位'},{cx:710,title:'后天八卦',dirs:['坎','艮','震','巽','离','坤','兑','乾'],sub:'罗盘常用方位'}];let parts=sets.map(s=>`<circle cx="${s.cx}" cy="262" r="172" fill="#fff" stroke="#c4d4c6" stroke-width="2"/>${Array.from({length:8},(_,i)=>{let a=i*45,p=xy(a,137,s.cx,262);return `<g><circle cx="${p[0]}" cy="${p[1]}" r="28" fill="${i%2?'#edf4e9':'#f8f1e5'}"/>${labelSvg(p[0],p[1]+8,s.dirs[i],25)}</g>`}).join('')}${labelSvg(s.cx,262,s.title,28)}${labelSvg(s.cx,294,s.sub,15,'#849487')}${labelSvg(s.cx,64,'北↑',20,'#9b724a')}`).join('');return svgShell(parts+labelSvg(479,495,'图示均采用现代“北上南下”的摆放方式',17,'#7b8f7d'),'先天八卦与后天八卦比较');}
function wuxingDiagram(){let names=['木','火','土','金','水'],c=['#648d64','#b9785b','#b79c68','#8c9290','#5a94a5'];let centers=names.map((n,i)=>{let a=(-90+i*72)*Math.PI/180;return [480+185*Math.cos(a),266+185*Math.sin(a)]});let defs=`<defs><marker id="wx-arrow" markerWidth="10" markerHeight="10" refX="6" refY="3" orient="auto"><path d="M0 0L6 3 0 6" fill="none" stroke="#799986" stroke-width="1.8"/></marker></defs>`;let links=centers.map((p,i)=>{let q=centers[(i+1)%5],dx=q[0]-p[0],dy=q[1]-p[1],len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len;return `<path d="M${p[0]+ux*53} ${p[1]+uy*53} L${q[0]-ux*58} ${q[1]-uy*58}" stroke="#7d9e8b" stroke-width="4" stroke-linecap="round" marker-end="url(#wx-arrow)" fill="none"/>`}).join('');let circles=centers.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="47" fill="${c[i]}"/><text x="${p[0]}" y="${p[1]+13}" text-anchor="middle" font-size="38" fill="#fff" font-weight="600">${names[i]}</text>`).join('');return svgShell(defs+links+circles+labelSvg(480,254,'相生',28)+labelSvg(480,288,'传统分类关系',17,'#798f81')+labelSvg(480,500,'顺着箭头记忆：木 → 火 → 土 → 金 → 水 → 木',19),'五行相生示意图');}
function terrainDiagram(){let mountains=`<path d="M0 260Q120 160 180 202Q285 68 360 171Q424 99 507 185Q574 65 658 179Q754 121 960 253V370H0Z" fill="#ceded0"/><path d="M0 316Q128 261 224 288Q364 223 484 301Q650 224 785 280Q876 248 960 279V385H0Z" fill="#a9c3ab"/><path d="M0 388L960 388V530H0Z" fill="#dce9da"/><path d="M42 447Q240 424 382 458Q496 483 617 440Q744 413 917 459" fill="none" stroke="#72b0b1" stroke-width="29" stroke-linecap="round"/>`;let buildings=Array.from({length:6},(_,i)=>{let x=400+i*75,y=343+(i%2)*4;return `<rect x="${x}" y="${y}" width="48" height="36" fill="#fdfcf4" stroke="#738e78" stroke-width="2"/><path d="M${x-5} ${y}l29-23 29 23" fill="#b98e77"/>`}).join('');return svgShell(mountains+buildings+labelSvg(310,122,'地貌与山势',22)+labelSvg(756,344,'村落建筑',19)+labelSvg(208,500,'水系与排水',19)+labelSvg(780,81,'示意 · 无真实坐标',16,'#a07f61'),'山川地势与建筑选址教学示意');}
function stemsDiagram(){let stems=['甲','乙','丙','丁','戊','己','庚','辛','壬','癸'],branches=['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'];let cols=[{x:62,y:100,w:400,title:'十天干',data:stems,color:'#6e9375',note:'其中戊、己不列入二十四山'},{x:495,y:100,w:403,title:'十二地支',data:branches,color:'#997c61',note:'十二项都进入二十四山'}];return svgShell(cols.map(c=>`${labelSvg(c.x,67,c.title,26,'#344f40','start')}${c.data.map((s,i)=>{let x=c.x+(i%5)*80,y=c.y+Math.floor(i/5)*106;return `<rect x="${x}" y="${y}" width="64" height="72" rx="10" fill="${c.color}" fill-opacity="${s==='戊'||s==='己'?'.23':'.11'}" stroke="${c.color}" stroke-opacity=".5"/><text x="${x+32}" y="${y+47}" font-size="32" text-anchor="middle" fill="#496253">${s}</text>`}).join('')}${labelSvg(c.x,c.y+265,c.note,16,'#819084','start')}`).join('')+labelSvg(480,493,'24山 = 8天干 + 12地支 + 4维卦（乾坤艮巽）',23),'天干地支与二十四山组成');}
function northDiagram(){return svgShell(`<defs><marker id="nb-arr" markerWidth="10" markerHeight="10" refX="7" refY="3" orient="auto"><path d="M0 0L7 3L0 6" fill="none" stroke="#8b7557" stroke-width="2"/></marker></defs><circle cx="350" cy="270" r="172" fill="#f3f7f0" stroke="#cad8c7" stroke-width="3"/><line x1="350" y1="270" x2="350" y2="75" stroke="#386c62" stroke-width="8" stroke-linecap="round" marker-end="url(#nb-arr)"/><line x1="350" y1="270" x2="437" y2="93" stroke="#ba7b52" stroke-width="8" stroke-linecap="round"/><path d="M350 164A106 106 0 0 1 397 175" stroke="#b59668" fill="none" stroke-width="4" stroke-dasharray="5 7"/>${labelSvg(350,60,'真北',24)}${labelSvg(487,106,'磁北（示意）',24,'#b0714c','start')}${labelSvg(680,240,'角度仅作概念示意',22)}${labelSvg(680,282,'当地磁偏角需要查询',18,'#809184')}${labelSvg(680,316,'不可直接用图估计',18,'#809184')}`, '真北和磁北的概念区别');}
function luoshuDiagram(){let v=[4,9,2,3,5,7,8,1,6];return svgShell(v.map((n,i)=>{let x=304+(i%3)*120,y=90+Math.floor(i/3)*116;return `<rect x="${x}" y="${y}" width="110" height="106" rx="7" fill="${i===4?'#e4eee0':'#fffcf5'}" stroke="#b5cbb5" stroke-width="2"/>${labelSvg(x+55,y+62,n,46,'#3b745f')}`}).join('')+labelSvg(480,55,'传统洛书九宫',25)+labelSvg(480,488,'上南 下北 · 横竖斜三数相加皆为15',21),'洛书九宫图');}
function defaultDiagram(i){let type=i<1?'terrain':i===1?'wuxing':i===2?'bagua':i===3?'stems':i===4?'mountain':i===5?'north':i>=12&&i<=23?'luoshu':i>=24?'mountain':'terrain';return ({terrain:terrainDiagram,wuxing:wuxingDiagram,bagua:baguaDiagram,stems:stemsDiagram,mountain:mountainDiagram,north:northDiagram,luoshu:luoshuDiagram})[type]();}
function diagramFigure(i){let typ=['传统环境观察示意','五行相生关系图','先后天八卦对照图','天干地支结构图','二十四山精密分区图','真北与磁北概念图'][i]||'知识体系示意';return `<figure class="edu-figure"><div class="figure-toolbar"><strong>${typ}</strong><button type="button" class="media-zoom" data-zoom-diagram="${i}">⛶ 放大图解</button></div>${defaultDiagram(i)}<figcaption>本站自主绘制矢量图，可无损放大。图解用于理解概念，涉及传统排列的内容按图注口径使用。</figcaption></figure>`;}
function quizWidget(i){const q=checkpointBank[i];if(!q)return '';let checked=gradeData['l'+i]||[];let cursor=Math.min(3,checked.length),passed=cursor>=3,task=q[Math.min(cursor,2)];return `<div class="lesson-checkpoint"><div class="checkpoint-head"><div><div class="eyebrow">INTERACTIVE CHECKPOINT</div><h3>本课掌握检验 <small>${cursor} / 3</small></h3></div><span class="${passed?'pill-success':'pill-neutral'}">${passed?'✓ 已通过':'答对三题才算掌握'}</span></div>${passed?`<div class="checkpoint-pass"><strong>本课已掌握</strong><p>已完成3道知识检验，可进入下一课，也可点击重新练习。</p><button class="btn btn-outline btn-small" data-check-reset="${i}">重新练习</button></div>`:`<p class="checkpoint-q">${task.q}</p><div class="checkpoint-opts">${task.options.map((x,k)=>`<button data-check-answer="${i}" data-opt="${k}" class="checkpoint-opt"><span>${'ABC'[k]}</span>${x}</button>`).join('')}</div><div class="checkpoint-feedback" id="checkpoint-feedback"></div><p class="hint-text">正确答案会立即保存到本机进度。回答错误可直接再试。</p>`}</div>`;}
function renderCourses(){let i=state.lesson,l=lessons[i],module=Math.floor(i/6);state.module=module;let [title,summary,body,conceptStr,stepStr,q,a]=l;let focus=advancedLessons[i],completed=lessonStatus(i),passed=(gradeData['l'+i]||[]).length===3;let sec=focus?`<div class="lesson-callout"><strong>本课学习目标</strong><p>${focus.aim}</p></div><div class="lesson-lead">${focus.lead}</div>${diagramFigure(i)}${focus.sections.map(([h,t])=>`<section class="chapter-section"><h3>${h}</h3><p>${t}</p></section>`).join('')}<div class="worked-example"><span class="small-label">WORKED EXAMPLE · 跟随推演</span><h3>把知识用在具体情境中</h3><p>${focus.example}</p></div><div class="common-mistake"><strong>常见错误</strong><p>${focus.mistake}</p></div><p class="lesson-tip">学习建议：${focus.related}</p>`:`<section class="chapter-section"><h3>核心讲解</h3><p>${body}</p></section>${diagramFigure(i)}${i===28?`<figure class="edu-figure"><div class="figure-toolbar"><strong>排龙参考图（来源待考）</strong><button class="media-zoom" data-zoom-original>⛶ 放大原图</button></div><img src="data:image/png;base64," alt="排龙诀原图" style="width:100%;display:block"/><figcaption>原始研习材料。原图的图形分层可识别，但起算流派及部分箭头依据尚待考证。</figcaption></figure>`:''}`;
 let practice=focus?quizWidget(i):`<h3 class="block-title">课堂检验</h3><div class="exercise-box"><div class="small-label">PRACTICE · 练习 ${minIndex(i)}</div><p>${q}</p><button class="btn btn-small btn-outline" id="show-answer">查看参考答案 ⌄</button><div class="answer" id="lesson-answer">${a}</div></div>`;
 $('view-courses').innerHTML=heading('LEARNING PATH · VERSION 2.0','系统课程','前六课已升级为完整教学示范，其余课程保留原内容并增加高清知识图解。',`<span class="tag warm">第 ${i+1} / 36 课</span>`)+`<div class="course-layout"><aside class="course-index card"><h3>全部课程 <span style="float:right;color:#99a79a;font-size:11px">${saved.done.length}/36 已完成</span></h3>${stages.map((s,si)=>`<div><button class="module-toggle" data-toggle-module="${si}"><span style="font-size:13px;color:#495e4e;font-weight:750">${si+1}. ${s.name}</span><span>${state.module===si?'收起':'展开'} ⌄</span></button><div class="module-lessons ${state.module===si?'':'hidden'}">${lessons.slice(si*6,si*6+6).map((x,j)=>{let n=si*6+j;return `<button class="lesson-row ${n===i?'selected':''} ${lessonStatus(n)?'completed':''}" data-lesson-select="${n}"><span class="lesson-num">${minIndex(n)}</span><span class="lesson-title">${x[0]}</span><span class="done-dot">${lessonStatus(n)?'✓':n<36&&(gradeData['l'+n]||[]).length===3?'●':'○'}</span></button>`}).join('')}</div></div>`).join('')}</aside><article class="reading-panel card"><div class="reading-top"><span class="tag">${stages[module].name} · 第 ${i+1} 课</span><span class="tag ${completed?'green':'gray'}">${completed?'✓ 已学完':'○ 待学习'}</span></div><h2 class="reading-title">${title}</h2><p class="reading-deck">${summary}</p><div class="reading-meta"><span>◷ ${focus?'约 25 至 35 分钟':'约 12 分钟'}</span><span>◈ 图解教学</span><span>✎ ${focus?'3道即时检验':'含练习与参考答案'}</span></div><div class="reading-body">${sec}<h3 class="block-title">本课关键词</h3><div class="concept-pills">${conceptStr.split('|').map(x=>`<span>${x}</span>`).join('')}</div><h3 class="block-title">跟着做</h3><ol class="study-steps">${stepStr.split('|').map(x=>`<li>${x}</li>`).join('')}</ol>${practice}<h3 class="block-title">我的学习笔记</h3><textarea id="lesson-note" class="reading-note" placeholder="写下你亲自推演的过程，或仍未弄懂的地方...">${htmlEscape(saved.notes[i]||'')}</textarea><p class="hint-text">笔记保存在浏览器。可以在“术语与文献”页导出完整学习档案。</p></div><div class="reader-footer"><button class="btn ${completed?'btn-soft':'btn-primary'}" id="mark-done" ${i<36&&!completed&&!passed?'disabled title="请先完成本课三道检验"':''}>${completed?'✓ 已完成 · 点击取消':i<36&&!passed?'完成三题后可标记':'完成本课 ✓'}</button><div class="nav-buttons"><button class="btn btn-small btn-outline" data-prev-lesson ${i===0?'disabled':''}>← 上一课</button><button class="btn btn-small btn-primary" data-next-lesson ${i===35?'disabled':''}>下一课 →</button></div></div></article></div>`;}
function caseVisual(c,large=false){const pic=galleryInfo[c.id];const ill=caseIllustration(c.kind);if(!pic)return `<div class="enhanced-case-art">${c.kind==='flat'?floorplanSvg(186,false):ill}<button class="media-zoom art-zoom" data-zoom-case="${c.id}">⛶ 高清放大</button></div>`;
return `<div class="photo-wrapper"><div class="real-case-fallback">${heritageVector(c.id)}<span>高精度矢量教学图 · 实景摄影联网可加载</span></div><img class="case-photo photo-overlay" loading="eager" src="${pic.image}" alt="${pic.name}" onload="this.classList.add('loaded')" onerror="this.remove()"/><div class="photo-tools"><button class="media-zoom" data-zoom-photo="${c.id}">⛶ 查看实景</button><a href="${pic.url}" target="_blank" rel="noopener noreferrer">原图及许可 ↗</a></div><div class="photo-credit">图解：本站自绘　|　联网照片：${pic.author} · ${pic.license} · Wikimedia Commons</div></div>`;}
function heritageVector(id){const items={hongcun:{label:'宏村 · 月沼与聚落',sub:'空间观察图 · 非精准测绘',hint:'山地 / 街巷 / 池塘 / 村落',color:'#74aaa8'},axis:{label:'北京中轴线 · 南北礼序',sub:'建筑轴线示意 · 非地理底图',hint:'南北轴线 / 建筑节奏 / 礼制空间',color:'#ac8862'},tulou:{label:'福建土楼 · 围合院落',sub:'圆形形制示意 · 不代表某一土楼',hint:'围合 / 入口 / 内院 / 山地',color:'#af9171'},suzhou:{label:'苏州园林 · 山水空间',sub:'园林构成示意 · 非实测平面',hint:'山石 / 水池 / 亭廊 / 游线',color:'#719d93'}};let t=items[id],g='';
if(id==='hongcun'){g=`<path d="M0 150Q125 80 230 139T460 112T710 119T960 111V360H0Z" fill="#bfcfc2"/><path d="M0 224Q126 190 244 212T520 202T960 197V400H0Z" fill="#99b69f"/>${Array.from({length:24},(_,i)=>{let x=295+(i%8)*63,y=191+Math.floor(i/8)*50;return `<rect x="${x}" y="${y}" width="39" height="26" fill="#f9f6e9" stroke="#7c9082" stroke-width="1.5"/><path d="M${x-3} ${y}l23-16 23 16" fill="#8b7e70"/>`}).join('')}<path d="M0 380Q280 350 450 388T960 382V530H0Z" fill="#dde5d8"/><ellipse cx="595" cy="393" rx="230" ry="74" fill="#82b6b1" stroke="#eaf6ea" stroke-width="7"/><ellipse cx="595" cy="394" rx="195" ry="54" fill="#a1cec7"/><path d="M461 457Q340 490 270 529" stroke="#80b6b5" stroke-width="27" fill="none"/>`;}
if(id==='axis'){g=`<rect x="310" y="0" width="330" height="530" fill="#f2e5d4"/><path d="M475 40V530" stroke="#ae6b58" stroke-width="5" stroke-dasharray="11 11"/>${[90,188,306,417].map((y,i)=>`<rect x="${i===2?348:378}" y="${y}" width="${i===2?254:194}" height="55" rx="2" fill="#dfc3a1" stroke="#8c6f55" stroke-width="3"/><path d="M${i===2?335:364} ${y}l${i===2?140:112}-31 ${i===2?140:112} 31" fill="#a36c5c"/>`).join('')}<g fill="#8cac92" opacity=".7"><circle cx="244" cy="204" r="42"/><circle cx="721" cy="344" r="56"/><circle cx="230" cy="435" r="53"/></g>`;}
if(id==='tulou'){g=`<path d="M0 243Q120 130 274 198T530 185T960 211V530H0Z" fill="#a9bf9d"/><path d="M0 303Q240 243 405 304T960 277V530H0Z" fill="#c1d2b5"/><ellipse cx="520" cy="315" rx="286" ry="180" fill="#9a8069" stroke="#f7f0df" stroke-width="11"/><ellipse cx="520" cy="315" rx="210" ry="118" fill="#ded3b9" stroke="#fbfaee" stroke-width="12"/><ellipse cx="520" cy="315" rx="164" ry="90" fill="#a6bea0"/><path d="M520 493V405" stroke="#fff5dc" stroke-width="23"/>${Array.from({length:36},(_,i)=>{let a=i*Math.PI/18;return `<circle cx="${520+244*Math.cos(a)}" cy="${315+145*Math.sin(a)}" r="5" fill="#eee6d8"/>`}).join('')}`;}
if(id==='suzhou'){g=`<rect x="96" y="100" width="768" height="355" fill="#d1dec8" stroke="#9caf9e" stroke-width="8"/><path d="M122 177Q218 95 325 175Q429 255 577 167Q710 99 832 184Q798 308 675 327Q534 385 408 303Q250 355 122 292Z" fill="#8bbdb2" stroke="#dceee3" stroke-width="9"/><g fill="#648a66">${[[176,153,44],[226,371,55],[769,332,66],[700,143,35]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/>`).join('')}</g><path d="M578 120l75-46 76 46v30H578z" fill="#b99a80"/><rect x="592" y="150" width="123" height="45" fill="#fff8e8" stroke="#b2997e" stroke-width="5"/><path d="M158 439Q331 389 448 421T823 395" fill="none" stroke="#ece7cf" stroke-width="15" stroke-dasharray="14 8"/>`;}
return svgShell(`${g}<rect width="960" height="80" fill="#fbfaf0" fill-opacity=".93"/>${labelSvg(42,41,t.label,28,'#2e5845','start')}${labelSvg(42,68,t.sub,16,'#789083','start')}<rect x="40" y="463" width="520" height="48" rx="9" fill="#fffdf2" fill-opacity=".94"/>${labelSvg(60,494,t.hint,20,'#527465','start')}`,'真实文化遗产图解 · '+t.label);
}
function caseTile(c){let pic=galleryInfo[c.id];return `<article class="card case-tile" role="button" tabindex="0" data-case="${c.id}"><div class="case-graphic case-graphic-v2">${pic?`<div class="thumb-vector">${heritageVector(c.id)}</div><img class="case-photo thumb-photo" loading="lazy" src="${pic.image}" alt="${pic.name}" onload="this.classList.add('loaded')" onerror="this.remove()"/>`:c.kind==='flat'?floorplanSvg(186,false):caseIllustration(c.kind)}<span class="case-type">${c.type==='real'?'真实建筑 · 资料与摄影有来源':'教学案例 · 参数均为模拟'}</span></div><div class="case-info"><div class="case-meta">${c.location}</div><h3>${c.title}</h3><p>${c.summary}</p><div class="case-open"><span>${c.id==='flat'?'进入完整五步实训':'查看图像与研究任务'}</span><span>↗</span></div></div></article>`;}
const flatSteps=[
 {title:'01 · 收集输入',desc:'先分清明确给出的模拟条件和仍然缺失的实测资料。',q:'模拟住宅给出的建筑朝向是多少？',type:'number',answer:186,explain:'原始案例假设朝向186°，同时假设住宅平面近似矩形。这些是假设条件，不是实测结果。'},
 {title:'02 · 测向定位',desc:'依据24山每山15°的区间，计算186°对应哪个山。',q:'186°属于哪个山？',type:'choice',options:['子山','午山','丁山','未山'],answer:1,explain:'午山的覆盖范围为172.5°至187.5°，186°落在范围内。'},
 {title:'03 · 分宫与边界',desc:'把北箭头、九宫分区和方位角放在同一张平面图上，注意187.5°的界线。',q:'若朝向变成189°，应选择哪个山？',type:'choice',options:['午山','丁山','未山','酉山'],answer:1,explain:'189°已经跨过187.5°分界，属于丁山187.5°至202.5°。'},
 {title:'04 · 辨别证据',desc:'哪些变量真实可验证，哪些传统判断无法据此推出？',q:'下列哪一项需要实际测量或查验后才能确认？',type:'choice',options:['186°在午山范围','假设住宅的真实年日照时数','24山每山15°','朝向加180°求相对方向'],answer:1,explain:'真实日照时间需要地理位置、遮挡、窗户等现场数据，无法由朝向独立推断。'},
 {title:'05 · 完成复核报告',desc:'明确本次模拟的结果、限制条件与未完成事项。',q:'面对未确认的真实建筑竣工年份，你应该怎样处理？',type:'choice',options:['假定是2024年','标记待核实，不生成确定宅盘','借用同小区其他楼的年份','忽略时间直接判断吉凶'],answer:1,explain:'传统宅盘起运等规则依赖额外时间条件；缺失时应明确标注。'}
];
function floorplanSvg(angle=186,showGrid=false){const rad=angle*Math.PI/180;const lineX=580+210*Math.sin(rad),lineY=370-210*Math.cos(rad);let grid=showGrid?`<g stroke="#ad7355" stroke-width="2.2" stroke-dasharray="10 7" fill="none"><path d="M350 195V548 M495 195V548 M350 310H785 M350 428H785"/></g>${['西北','北','东北','西','中','东','西南','南','东南'].map((p,i)=>{const x=421+(i%3)*145,y=257+Math.floor(i/3)*117;return `<rect x="${x-31}" y="${y-23}" width="62" height="28" rx="6" fill="#fff9e9" stroke="#c88e5d"/><text x="${x}" y="${y-4}" font-size="17" text-anchor="middle" fill="#8e5a38">${p}</text>`}).join('')}`:'';
return svgShell(`<defs><marker id="flat-arr" orient="auto" markerWidth="9" markerHeight="9" refX="8" refY="3"><path d="M0 0L8 3 0 6" fill="none" stroke="#b56849" stroke-width="2"/></marker></defs><g stroke="#8ca18d" stroke-width="8" fill="#fffef7"><rect x="350" y="195" width="435" height="353" rx="5"/><path d="M350 320H785 M495 195V548 M640 320V548"/></g><g fill="#d7e8df"><rect x="367" y="210" width="110" height="94" rx="4"/><rect x="516" y="340" width="107" height="192" rx="4"/><rect x="661" y="340" width="103" height="88" rx="4"/></g><g fill="#fff" stroke="#a7b9a7" stroke-width="3"><rect x="392" y="240" width="55" height="24" rx="4"/><rect x="540" y="385" width="65" height="70" rx="4"/><rect x="672" y="375" width="70" height="35" rx="4"/></g><g stroke="#56a7bb" stroke-width="10"><path d="M370 548H468 M511 548H625 M651 548H749"/></g><g fill="#60786a" font-size="16" text-anchor="middle"><text x="422" y="285">卧室</text><text x="570" y="283">餐厨</text><text x="710" y="283">入口</text><text x="568" y="494">客厅</text><text x="711" y="473">书房</text></g><line x1="580" y1="370" x2="${lineX}" y2="${lineY}" stroke="#b56849" stroke-width="5" marker-end="url(#flat-arr)"/><circle cx="580" cy="370" r="8" fill="#b56849"/><path d="M183 155v-89" stroke="#2b6f59" stroke-width="5"/><path d="M172 86l11-24 11 24" fill="#2b6f59"/>${labelSvg(183,194,'北↑',22)}${labelSvg(188,285,'教学虚构平面',24,'#546f5b')}${labelSvg(188,324,'N向上',18,'#859587')}${labelSvg(188,361,'采光窗示意为蓝色',16,'#859587')}${labelSvg(580,585,'朝向 '+fmt(angle)+'° · '+mountainInfo(angle).m+'山',19,'#a56849')}${grid}`,'模拟住宅平面与九宫分区','0 0 960 620');}
function flatTrainer(){let pos=upgradeState.flatStep,p=flatSteps[pos],done=gradeData.flatDone||[],completed=done.includes(pos);let answerPart=p.type==='number'?`<label class="form-label" for="flat-answer-num">输入朝向度数</label><div class="trainer-form"><input type="number" id="flat-answer-num" placeholder="如 186" min="0" max="359.99" step="0.1"/><button class="btn btn-primary" data-flat-check>提交</button></div>`:`<div class="checkpoint-opts">${p.options.map((o,k)=>`<button class="checkpoint-opt" data-flat-choice="${k}"><span>${'ABCD'[k]}</span>${o}</button>`).join('')}</div>`;return `<div class="flat-training card"><div class="eyebrow">GUIDED CASE STUDY</div><div class="case-stage-nav">${flatSteps.map((s,i)=>`<button class="case-stage ${i===pos?'current':''} ${done.includes(i)?'passed':''}" data-flat-step="${i}"><span>${done.includes(i)?'✓':i+1}</span><small>${s.title.split(' · ')[1]}</small></button>`).join('')}</div><div class="flat-training-grid"><div><div class="flat-illustration">${floorplanSvg(upgradeState.flatAngle,upgradeState.flatGrid)}</div><div class="lab-inline-toolbar"><label>朝向 <input id="flat-live-angle" aria-label="当前模拟朝向" type="number" min="0" max="359.99" step="0.1" value="${upgradeState.flatAngle}"/> °</label><button class="btn btn-small btn-outline" data-flat-grid>${upgradeState.flatGrid?'关闭九宫网格':'叠加九宫网格'}</button><button class="media-zoom" data-zoom-floor>⛶ 放大图</button></div><p class="caption">户型比例、朝向和房间布置均为自拟教学数据，九宫网格按简化矩形几何分区显示。</p></div><section><h3>${p.title}</h3><p class="lesson-deck">${p.desc}</p><div class="exercise-box"><p><strong>${p.q}</strong></p>${completed?`<div class="checkpoint-pass"><strong>✓ 已完成此步骤</strong><p>${p.explain}</p></div>`:answerPart}<div id="flat-feedback" class="checkpoint-feedback"></div></div><div class="trainer-status">已通过 ${done.length} / 5 步，${done.length===5?'可以导出完整报告':'继续核对当前步骤'}</div><div class="trainer-nav"><button class="btn btn-outline btn-small" data-flat-step="${Math.max(0,pos-1)}" ${pos===0?'disabled':''}>上一环节</button><button class="btn btn-primary btn-small" data-flat-step="${Math.min(4,pos+1)}" ${pos===4?'disabled':''}>下一环节 →</button></div></section></div></div>`;}
function renderCases(){let list=cases.filter(c=>state.caseFilter==='all'||c.type===state.caseFilter);if(state.caseId){const c=cases.find(c=>c.id===state.caseId);if(c){renderCaseDetail(c);return}}$('view-cases').innerHTML=heading('CASE STUDY · REAL AND SIMULATED','案例研习馆','真实建筑配摄影来源与观察任务，模拟住宅提供五步演练。高清实景照片联网加载，断网时自动回退到可缩放矢量图。')+`<div class="case-controls"><button class="chip ${state.caseFilter==='all'?'active':''}" data-case-filter="all">全部案例 · 7</button><button class="chip ${state.caseFilter==='real'?'active':''}" data-case-filter="real">文化遗产 · 4</button><button class="chip ${state.caseFilter==='sim'?'active':''}" data-case-filter="sim">情境实训 · 3</button></div><div class="case-grid">${list.map(caseTile).join('')}</div><div class="notice">观察资料与传统解释分开记录。照片来自对应景观的开放许可媒体文件；如需离线展示真实摄影，请在部署时取得并按许可要求打包图片。网站始终可离线使用矢量图解。</div>`;}
function renderCaseDetail(c){let source=c.source!==null?sources[c.source]:null;let pic=galleryInfo[c.id];$('view-cases').innerHTML=`<div class="case-detail card"><button class="back-link" data-back-cases>← 返回案例馆</button>${caseVisual(c,true)}<div class="detail-header"><div class="eyebrow">${c.type==='real'?'REAL HERITAGE · EVIDENCE BASED':'SIMULATED · GUIDED PRACTICE'}</div><h2>${c.title}</h2><p>${c.location}　·　${c.period}</p></div>${pic?`<p class="case-photoinfo"><strong>观察这张照片：</strong>${pic.desc}</p>`:''}<div class="detail-columns"><div class="detail-panel"><h4>01 · 已知事实与模拟条件</h4><ul>${c.facts.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="detail-panel"><h4>02 · 观察与分析方法</h4><ul>${c.analysis.map(t=>`<li>${t}</li>`).join('')}</ul></div></div><div class="detail-panel" style="margin-top:16px"><h4>03 · 哪些判断仍然缺乏资料</h4><p>${c.limits}</p></div>${c.id==='flat'?flatTrainer():`<div class="exercise-box" style="margin-top:18px"><span class="small-label">CASE ACTIVITY</span><p>${c.question}</p></div>`}${source?`<div class="case-citation">历史资料：${source.org} · <a target="_blank" rel="noopener noreferrer" href="${source.url}">打开原始资料 ↗</a>${pic?`<div>摄影授权：<a target="_blank" rel="noopener noreferrer" href="${pic.url}">${pic.author} / ${pic.license}</a>，请保留摄影署名及许可条件。</div>`:''}</div>`:c.id==='flat'?`<div class="report-actions"><button class="btn btn-primary" data-export-flat ${((gradeData.flatDone||[]).length!==5)?'disabled':''}>导出五步实训报告 TXT</button><button class="btn btn-outline" data-flat-reset>重新开始五步训练</button></div>`:`<div class="notice">本案例提供虚构参数，仅用于练习。</div>${fieldForm(c)}`}</div>`;}
function flatExport(){let done=gradeData.flatDone||[];if(done.length!==5){toast('先完成5步演练');return}let text=`形理书院 V2 | 模拟住宅五步实训报告\n生成时间：${new Date().toLocaleString('zh-CN')}\n案例性质：完全模拟，不涉及真实测绘\n------------------------------------\n模拟朝向：186°（原始条件）\n山位：午山，172.5° 至 187.5°\n相对坐山：子山\n关键边界：187.5°；模拟改为189°时转为丁山\n九宫：在矩形图上按照简化几何中心示意分区\n已完成步骤：${done.slice().sort().map(n=>flatSteps[n].title).join('，')}\n\n仍未核实：建筑年代、方位基准、重复测量误差、真实日照、通风、消防等。\n研究边界：不生成真实玄空宅盘或运势吉凶结论。\n`;let b=new Blob(['\ufeff',text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='形理书院V2_住宅五步实训报告.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openImageModal(content,title){let wrap=document.getElementById('edu-media-modal');if(!wrap){wrap=document.createElement('div');wrap.id='edu-media-modal';wrap.className='edu-media-modal';document.body.appendChild(wrap)}wrap.innerHTML=`<div class="edu-media-dialog" role="dialog" aria-modal="true" aria-label="${htmlEscape(title)}"><div class="edu-media-top"><strong>${htmlEscape(title)}</strong><button class="btn btn-small btn-outline" data-close-media>关闭 ✕</button></div><div class="edu-media-body">${content}</div></div>`;wrap.classList.add('open');document.body.style.overflow='hidden';}
function closeImageModal(){let x=document.getElementById('edu-media-modal');if(x)x.classList.remove('open');document.body.style.overflow='';}
function extraEvents(e){let opt=e.target.closest('[data-check-answer]');if(opt){let i=Number(opt.dataset.checkAnswer),idx=(gradeData['l'+i]||[]).length,q=checkpointBank[i][idx];const f=document.getElementById('checkpoint-feedback');if(Number(opt.dataset.opt)===q.correct){let d=gradeData['l'+i]||[];d.push(q.correct);gradeData['l'+i]=d;persistGrade();if(f){f.className='checkpoint-feedback correct';f.innerHTML='<strong>回答正确。</strong> '+q.why}setTimeout(()=>{if(state.view==='courses'&&state.lesson===i)renderCourses()},320);}else if(f){f.className='checkpoint-feedback incorrect';f.innerHTML='<strong>再想一想。</strong> '+q.why}return}
 let reset=e.target.closest('[data-check-reset]');if(reset){delete gradeData['l'+reset.dataset.checkReset];persistGrade();renderCourses();return}
 let fs=e.target.closest('[data-flat-step]');if(fs){upgradeState.flatStep=Number(fs.dataset.flatStep);renderCaseDetail(cases.find(c=>c.id==='flat'));return}
 if(e.target.closest('[data-flat-grid]')){upgradeState.flatGrid=!upgradeState.flatGrid;renderCaseDetail(cases.find(c=>c.id==='flat'));return}
 if(e.target.closest('[data-flat-check]')){let n=Number(document.getElementById('flat-answer-num')?.value);let f=document.getElementById('flat-feedback');if(document.getElementById('flat-answer-num')?.value!==''&&Math.abs(n-186)<0.01)completeFlatStep();else if(f){f.textContent='这道题需要从案例开头读取原始设定的朝向186°，请再试。';f.className='checkpoint-feedback incorrect'}return}
 let fc=e.target.closest('[data-flat-choice]');if(fc){let x=flatSteps[upgradeState.flatStep],f=document.getElementById('flat-feedback');if(Number(fc.dataset.flatChoice)===x.answer)completeFlatStep();else if(f){f.textContent='答案有误。'+x.explain;f.className='checkpoint-feedback incorrect'}return}
 if(e.target.closest('[data-flat-reset]')){gradeData.flatDone=[];persistGrade();upgradeState.flatStep=0;renderCaseDetail(cases.find(c=>c.id==='flat'));return}
 if(e.target.closest('[data-export-flat]')){flatExport();return}
 if(e.target.closest('[data-zoom-diagram]')){let i=Number(e.target.closest('[data-zoom-diagram]').dataset.zoomDiagram);openImageModal(defaultDiagram(i),lessons[i][0]);return}
 if(e.target.closest('[data-zoom-original]')){openImageModal('<img src="data:image/png;base64," alt="排龙诀原图"/>','排龙诀原始图片');return}
 if(e.target.closest('[data-zoom-floor]')){openImageModal(floorplanSvg(upgradeState.flatAngle,upgradeState.flatGrid),'模拟住宅平面图');return}
 let zp=e.target.closest('[data-zoom-photo]');if(zp){let id=zp.dataset.zoomPhoto,p=galleryInfo[id];let loaded=!!document.querySelector('.photo-wrapper .photo-overlay.loaded');openImageModal((loaded?`<img src="${p.image}" alt="${p.name}"/>`:heritageVector(id))+`<p class="caption">${loaded?'真实摄影':'当前展示高清矢量教学图。网络可用时可访问真实摄影原图。'} · <a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.author} / ${p.license} · 查看图片原始来源</a></p>`,p.name);return}
 let zc=e.target.closest('[data-zoom-case]');if(zc){let c=cases.find(x=>x.id===zc.dataset.zoomCase);openImageModal(c.id==='flat'?floorplanSvg(186,false):caseIllustration(c.kind),c.title);return}
 if(e.target.closest('[data-close-media]')||e.target.id==='edu-media-modal'){closeImageModal();return}
 if(e.target.closest('[data-export-study]')){try{
  const out={version:'5.2',exportTime:new Date().toISOString(),progress:saved,mastery:gradeData,visualNotes:v32VisualNotes,labs:JSON.parse(localStorage.getItem(XingliCore.studyKeys.labs)||'{}'),practice:JSON.parse(localStorage.getItem(XingliCore.studyKeys.practice)||'{"answers":{}}'),portfolio:window.XingliOutcomes?window.XingliOutcomes.snapshot():JSON.parse(localStorage.getItem(XingliCore.studyKeys.portfolio)||'{}')};
  XingliCore.cleanStudyArchive(out,cases.map(c=>c.id));
  const b=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),a=document.createElement('a');if(b.size>XingliCore.studyMaxBytes)throw Error('学习档案超过8MB，请先缩减过长的笔记或报告');const u=URL.createObjectURL(b);a.href=u;a.download='形理书院_学习档案备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);toast('已导出学习记录；户型图片请另存完整项目');
 }catch(error){toast('导出失败：'+error.message)}return}

}
function completeFlatStep(){let pos=upgradeState.flatStep,d=gradeData.flatDone||[];if(!d.includes(pos))d.push(pos);gradeData.flatDone=d;persistGrade();renderCaseDetail(cases.find(c=>c.id==='flat'));toast('本步骤已通过');}
function extraInputs(e){if(e.target.id==='flat-live-angle'){let v=Number(e.target.value);if(e.target.value!==''&&v>=0&&v<360){upgradeState.flatAngle=rounded(v);let el=document.querySelector('.flat-illustration');if(el)el.innerHTML=floorplanSvg(v,upgradeState.flatGrid)}}}
const originalRenderResources=renderResources;
renderResources=function(){originalRenderResources();let v=$('view-resources');let el=document.createElement('div');el.className='archive-backup card';el.innerHTML=`<div><div class="eyebrow">STUDY ARCHIVE</div><h3>学习档案备份</h3><p>包含36课进度与检验、案例训练、两类笔记、工具实训、飞星练习、测向实训及综合案例报告。户型图片与校准参数请到平面图工具另存“完整项目 JSON”。导入会替换文件包含的记录；旧版未包含的笔记、实训和案例报告保留。</p></div><div class="archive-buttons"><button class="btn btn-outline" data-v5-target="v5-plan">户型项目备份 →</button><button class="btn btn-primary" data-export-study>导出学习档案 ↓</button><label class="btn btn-outline restore-file-label" for="restore-study">导入并恢复 ↑</label><input id="restore-study" type="file" accept="application/json,.json" hidden></div>`;v.prepend(el)};
const originalRenderHome=renderHome;
renderHome=function(){originalRenderHome();let hero=document.querySelector('#view-home .hero-content');if(hero){let e=document.createElement('div');e.className='version-ribbon';e.textContent='V2.0 · 高清图解 / 分步教学 / 实操检验';hero.prepend(e)}let col=document.querySelector('#view-home .home-columns');if(col){let e=document.createElement('div');e.className='new-learning-strip card';e.innerHTML=`<div><div class="eyebrow">NEW IN 2.0</div><h3>从看懂，到自己能做</h3><p>前6节已升级为精讲课，每节配合无损矢量图解与3道即时检验。住宅模拟案例加入完整5步实训。</p></div><div><button class="btn btn-primary" data-go="courses" data-lesson="0">开始精讲课程 →</button><button class="btn btn-outline" data-case="flat">打开住宅实训 →</button></div>`;col.parentNode.insertBefore(e,col)}};
document.addEventListener('click',extraEvents);
document.addEventListener('input',extraInputs);
document.addEventListener('change',async e=>{
 if(e.target.id!=='restore-study')return;const file=e.target.files?.[0];if(!file)return;
 try{
  if(file.size>XingliCore.studyMaxBytes)throw Error('档案超过8MB，请检查文件');
  const next=XingliCore.cleanStudyArchive(JSON.parse(await file.text()),cases.map(c=>c.id));
  XingliCore.writeStudyArchive(localStorage,next);
  saved=next.progress;for(const key of Object.keys(gradeData))delete gradeData[key];Object.assign(gradeData,next.mastery);
  if(next.visualNotes!==undefined)v32VisualNotes=next.visualNotes;
  state.lesson=saved.lastLesson;updateProgress();renderCourses();renderResources();
  window.dispatchEvent(new CustomEvent('xingli-study-restored',{detail:{portfolioRestored:next.portfolio!==undefined}}));
  toast('36课检验与案例记录已恢复；户型项目需单独导入');
 }catch(error){toast('导入失败：'+error.message)}finally{e.target.value='';}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeImageModal()});

/* V3.0 全课程精讲资料：每课的知识目标、三节讲义、示例、误区与检验题独立设置 */
const v3CourseData = [
// 07—12 形势与环境
{aim:'能够用一张观察卡分别描述龙、穴、砂、水、向，并指出哪些需要实地核查。',lead:'到一处山地聚落，先别急着判断吉凶。把视线从远山移到选址点，再观察两侧地形、附近水道，最后才记录入口与建筑的朝向。五个术语帮助你系统观察一处场地。',sections:[
['从远及近辨认五个对象','“龙”传统上指山势及山脉延伸，“穴”指拟选的落址点，“砂”指周边环抱或对峙的山丘、地物，“水”指河沟、池塘、径流，“向”涉及场地与建筑的朝向。现代研究可以分别标出地形、用地、遮挡物、水体及测向线。'],
['不要把图形当作现场事实','航拍可以看出房屋与道路关系，却很难准确测量坡度和地下水。遥感底图需要比例尺、影像年份、坐标和许可；一个“水”字不能替代洪水位、排水坡度与积水风险。先制作事实表，再记录传统象义。'],
['练习构造观察卡','示例记录：远处有山脊（待核实海拔）；场地位于谷地台地（待核实高程）；东侧有林带（实景可见）；南侧临河（地图可见）；院落轴线大致朝南（尚未实测）。把证据状态逐项标出。']],example:'用宏村的航拍或地图辨认山体、水道、建筑群与主要通行路径，只能确认看得到的关系；具体“来龙”仍需要流派定义及地形证据。',mistake:'把“后方有楼”自动叫作“靠山”，随后直接给出健康、财运结论。',related:'画一张山、水、路、建筑四色图，至少给三条观察附上照片或地图来源。',diagram:'landscape'},
{aim:'能看懂等高线疏密与坡面方向，提出至少三项场地风险核查问题。',lead:'山势高低影响水往哪里流、道路如何修、建筑如何布置。传统“寻龙”常讨论起伏，现代图纸则把这些信息变为可量测的高程和坡度。',sections:[
['先读等高线','同一条等高线上的点具有相同高程。等高线越密，通常表示坡度越陡；越疏，坡地越缓。注意图中等高距和比例尺，不能仅凭线条密度比较不同地图的陡缓。'],
['分清分水岭与汇水沟','山脊大致是水流分向两侧的地带，谷沟则容易汇集上坡来水。沿等高线形成的V字形可辅助判断谷脊，但要结合标高数字确认方向。坡脚住宅需核实落石、滑坡与地表径流。'],
['把风险调查写入清单','样例：屋后坡度多少？上坡是否有截水沟？基坑和挡土墙是否经过专业设计？是否处于地质灾害风险区？这些问题需要地形测绘与专业报告回应。']],example:'两块地中，A坡地等高线相距20毫米、B相距5毫米；若比例尺与等高距相同，B地一般更陡。',mistake:'看到“背山”就判定选址安全，忽视暴雨、地灾和工程排水条件。',related:'找一张真实地形图，标出等高距、坡度方向、可能汇水位置。',diagram:'contour'},
{aim:'能够画出一个聚落的主要水道与道路，并区分水系事实与水法解释。',lead:'历史聚落常依赖水源、运输与耕作，水道与道路也塑造街巷和出入口。把两种网络画在一起，有助于看清生产生活的空间组织。',sections:[
['追踪水的来源和去向','先找河流上游、下游、水池、排水沟及可能的洪泛区。静态照片未必说明流向；流速、季节涨落和最高水位要查资料。历史水系是否被改造，也应通过不同年份的图纸检验。'],
['标记道路与入口','在平面图上找道路等级、步行入口、机动车出入口和消防通道。传统文献常把道路与水路类比，但把车流称作“虚水”仅是一种术数比附，现实交通效率要依据流量与设计规范衡量。'],
['做一张图层叠加图','建议四层：水道蓝色、道路灰色、建筑深灰、坡向箭头橙色。由图层提问：高流量道路是否穿过村落核心？雨水会否向建筑入口汇集？']],example:'宏村的月沼、水渠和南湖是可查证的水系统要素。用历史资料确认修筑年代与用途，再研究传统文化对其布局的解释。',mistake:'单凭道路弯曲程度认定吉凶，忽略行人安全、过街距离和积水。',related:'在真实地图上找一条明确标示流向的水道，同时标出居民通往水边的路线。',diagram:'network'},
{aim:'能够设计最基本的采光、通风、噪声观测记录，并写明测量限制。',lead:'居住体验中的日照、通风、温湿度与噪声都可以实测。理解这些物理条件，也有助于判断传统“藏风”“向阳”等表述包含了哪些可观察的经验。',sections:[
['日照与遮挡','太阳高度和方位随纬度、季节及时间变化。窗朝南也可能被高楼遮挡。完整判断需建筑位置、相邻建筑轮廓、窗台高度和日照计算，不能仅凭罗盘方位推断每年日照小时数。'],
['通风与微气候','有进风口、出风口不代表全年通风良好，风压、热压、开口位置都会影响室内换气。观察时应记录窗户开启状态、风速风向与测量时段。不要把“穿堂风”当成全年固定现象。'],
['噪声与热舒适','临主干路可能增加噪声与颗粒物暴露，西晒可能提高夏季冷负荷；是否超标要测量。用表格分开记录可测指标、时段、测量工具和是否达标。']],example:'两套朝南住宅，A无遮挡、B南侧紧邻高层。即使方位角相同，冬季日照条件也可能不同。',mistake:'把传统“阳气足”直接视为符合建筑日照标准，或把看似透风等同于空气质量优。',related:'分别选择夏季和冬季的一个时间段，建立观测表，避免用一次测量代表全年。',diagram:'sun'},
{aim:'能够用统一坐标口径评估楼间距、出入口、交通与消防条件。',lead:'现代办公楼和城市住宅的核心矛盾常是空间拥挤、复杂交通和使用功能分区。传统选址概念仍可作为文化研究对象，但工程事实优先来自规划和建筑资料。',sections:[
['先画城市片区','标出地块北向、建筑轮廓、临街面、城市主干道以及人车入口。历史照片与今日地图必须分开标注年份，防止把改建后的现状当作原始选址条件。'],
['收集三个必要参数','最基本的是建筑高度与楼间距、房间窗墙开口、道路及行人流线。涉及消防车道、消防登高场地或疏散宽度时必须查现行工程规范和项目竣工资料。'],
['给结论标证据等级','可直接观察的记为A；来自官方图纸的记为B；来自未经验证的网络介绍记为C；仅有传统解释则写“术数观点”。这样后期新增资料可更新结论。']],example:'模拟办公楼主入口向103°，可用二十四山工具得到乙山；但电梯厅入口、主立面与建筑朝向未必一致，需先明确立向基准。',mistake:'把楼宇大堂装饰朝向当作整栋建筑实际轴线。',related:'找一张城市办公地块总平面，分层标出入口、绿化、主要道路、消防通道。',diagram:'city'},
{aim:'能够按照统一模板完成一次现场勘察，并标注误差和待核实项。',lead:'无论研究传统风水还是现代空间环境，可信的案例都要能让第二个人复核。现场记录是连接图、文字、照片与测量结果的基础。',sections:[
['建立基本档案','记录案例名称、位置范围、观测日期、天气、测点编号、设备、坐标北向、照片序号与地图来源。真实住户的详细地址及个人信息不宜公开。'],
['分开事实、推演和结论','例如“测点A三次读数185.8°、186.2°、186.0°”是数据；“按本站二十四山规则为午”是计算；“传统教材称午属于某元龙”是规则引述。它们需要不同证据。'],
['明确哪些材料仍缺失','没有建筑年代就不能给出确定宅运；缺少当地磁偏角就不能声称磁北已换算真北；没有消防资料就不能评价疏散安全。报告结尾保留“待补证据”。']],example:'实训表的每条结论都填写“数据、来源、计算方式、未证实事项”四列，另一位学习者应能用同一输入重算。',mistake:'把实测角度和推演吉凶写在同一个“结论”栏，失去审计性。',related:'打开住宅实训案例，导出报告，检查是否明确写出了假设和限制。',diagram:'record'},
// 13—18 理气基础
{aim:'能够还原洛书九宫数字，理解宫位与飞泊路径各自的作用。',lead:'洛书把固定数字安排在九个宫位，飞星则沿另一条规定的访问次序计算星数。要避免把“宫位数字”与“当年落宫的星数”混为一谈。',sections:[
['记住固定洛书','传统南上北下画法：上行4、9、2，中行3、5、7，下行8、1、6。每行、每列及两条对角线之和都是15，因此被称为三阶幻方。'],
['区分位置和移动','巽宫长期位于东南方，常用本位数4；但在某一运盘或年盘里，这个宫的飞星数可以发生变化。位置的名称不随推演改变。'],
['用固定路线走九宫','飞泊路线为中→乾→兑→艮→离→坎→坤→震→巽。顺飞表示沿路线填入递增数字；逆飞填入递减数字。路线与地图上的顺时针方向并不相同。']],example:'5入中顺飞：乾6、兑7、艮8、离9、坎1、坤2、震3、巽4，恰好复原洛书。',mistake:'把九宫图简单按九个格子从左到右填写1至9。',related:'画一张空白3×3格，先填宫名、再填洛书数，最后用箭头标出飞泊路径。',diagram:'flight'},
{aim:'把南上北下的传统九宫与北上南下的现代地图正确互换。',lead:'地图颠倒是初学阶段最常见的连锁错误。只需先写清北箭头，再将八个方位逐一对应，后续计算就不会因为画法不同而全部错位。',sections:[
['宫与八卦一一对应','后天八卦中，坎北、艮东北、震东、巽东南、离南、坤西南、兑西、乾西北，中间为中宫。固定宫位无论翻转纸张都不改变实际方向。'],
['地图口径转换','现代平面图北在上：北方在图顶。传统盘南在上：南方排在顶行中央。二者能表达同一建筑，只要旋转180°并同步调整标注。'],
['叠加房屋平面图','给房屋选定中心后，可以在其上覆盖九宫方格；但复杂外轮廓、单元房、商办多入口均可能对中心点产生争议，应保留几种可比方案。']],example:'传统九宫的左上角是巽宫东南；现代北上地图的左上角对应乾宫西北。请勿把同一位置的标签直接搬过去。',mistake:'复制传统“4 9 2”盘到现代上北地图，却仍把上行当成北侧。',related:'尝试将九宫图纸旋转180°，逐一读出八个方位。',diagram:'dualgrid'},
{aim:'熟记九星数字和名称，并正确区分九星术数标签与物理事实。',lead:'一白贪狼、二黑巨门直到九紫右弼是一套传统命名。无论学流年盘、宅盘还是排龙图，首先保证数字和名称映射准确。',sections:[
['数字与星名对应','1贪狼、2巨门、3禄存、4文曲、5廉贞、6武曲、7破军、8左辅、9右弼。不同资料还常附白黑碧绿黄白赤白紫等色名。'],
['同一星可以出现在不同盘','流年盘显示某年宫位中的星；运盘由宅运决定；山盘和向盘还与坐向有关。虽然数字相同，它们在三张盘里的身份不同。'],
['传统吉凶语汇有时代与门派限制','“吉星”“凶星”是传统分类，不直接代表对应房间的安全、健康或收入变化。观察建筑问题仍需结合水电、消防、结构、日照等具体证据。']],example:'随机抽出数字4、7、9，应能立即说出文曲、破军、右弼，并能解释数字不等于实测环境强度。',mistake:'看到“7赤”就未经核查认定某房间有实际危险。',related:'用九宫练习随机点选宫位，口述星名，直到九个全部熟悉。',diagram:'nine'},
{aim:'理解三元九运与20年一运的时间框架，并识别年界问题。',lead:'常见三元九运把180年分成9个20年大运，包含上元、中元、下元。时间框架是玄空学推演的输入之一，须明确何时起算。',sections:[
['时间大框架','上元一、二、三运；中元四、五、六运；下元七、八、九运。常见近代划分是1984至2003年为七运，2004至2023年为八运，2024至2043年为九运。'],
['分清运与年','宅运是推演特定建筑宅盘时使用的长期条件；流年盘则按年度变更，二者会共同出现在传统分析里。不能仅因为现在进入九运，就把所有老楼自动视作九运宅。'],
['边界必须交代','一些玄空教材以立春附近为年运转换点。本站简化实验工具以公历年份作演示；若研究年界或特殊改建情形，应查明采用的教材和实际起用资料。']],example:'假设住宅2012年起用，按常见时间划分属八运；2026年仍可同时观察九运时代及2026年度的流年盘，两个概念不能替代。',mistake:'把2026年的新流年中宫数字当成宅盘的元运数字。',related:'制作1984、2004、2024、2044的连续时间线，并说出每段所处元运。',diagram:'timeline'},
{aim:'识别地元、天元、人元三个分组，学会查24山阴阳分类表。',lead:'“元龙”是玄空起盘所需的分类表。许多网络口诀只写阴阳却不解释分类来源，初学者容易直接用坐山本身的阴阳决定起飞方向。',sections:[
['每卦三山的结构','每个45°卦宫覆盖三山，通常按地元、天元、人元三类分配。例如坎宫壬（地元）、子（天元）、癸（人元）；离宫丙（地元）、午（天元）、丁（人元）。'],
['查表确认阴阳','天元龙阳为乾坤艮巽，阴为子午卯酉；地元龙阳为甲庚壬丙，阴为辰戌丑未；人元龙阳为寅申巳亥，阴为癸丁乙辛。需对照教材版本及特殊条件。'],
['应用时先确定星所属卦','山盘或向盘顺逆，要看进入中宫的运星在洛书本位属于哪个卦，再取该卦同元龙山的阴阳。不能将“坐山是阴”直接作为山盘逆飞的充分依据。']],example:'坐子属天元龙；假设山星入中数为4，4本位为巽卦，巽卦天元龙为巽（阳），因此在本教学规则里顺飞。',mistake:'把“子山属阴”直接推出“山盘一定逆飞”，遗漏了入中星对应卦这个关键步骤。',related:'用三元龙对照表回答：壬、子、癸分别是哪一类？',diagram:'dragon'},
{aim:'能够描述立极与测向的争议来源，判断输入何时不足以起盘。',lead:'宅盘计算往往看似简单，但前提是建筑中心、主要朝向和起用时间被明确定义。对于复杂多边形建筑和多个大门，输入定义本身就是难点。',sections:[
['立极点来自建筑对象','普通矩形户型容易找到几何中心。L型楼体、群楼连接体、层层退台和商业裙房，应先确定研究单元及采用的中心原则。'],
['朝向不总等于大门方向','建筑立向可取主立面、采光面、建筑轴线等不同口径。不同玄空流派和建筑类型的做法可能不同。应先声明采用哪种口径，并在图上画出方向线。'],
['量测误差决定结论强度','187.4°距离午丁边界只有0.1°。若手机读数误差±2°，可能覆盖两个山位；应标为待复核，或给出区间和两种可能，不能假装精确。']],example:'一个商办项目的塔楼朝向95°、主入口朝向130°。在没有定义所研究的建筑单元与立向规则前，不应输出唯一宅盘。',mistake:'忽视磁北与真北的差别，直接用门口手机一次读数计算全年吉凶。',related:'在案例馆的模拟办公楼与住宅之间切换，记录不同建筑的中心选点难题。',diagram:'center'},
// 19—24 玄空飞星
{aim:'理解运星入中、沿飞泊路径顺飞，独立排出八运和九运运盘。',lead:'运盘是整个宅盘的底图。它只需输入元运数字，按照中宫、乾、兑、艮、离、坎、坤、震、巽的固定路线顺飞。',sections:[
['把运数放在中宫','例如八运把8放中宫，九运把9放中宫。不论具体坐向，运盘的第一步都相同。'],
['沿路线逐宫填数','八运：中8、乾9、兑1、艮2、离3、坎4、坤5、震6、巽7。每推进一宫，数字加1，超过9从1重新开始。'],
['检查每宫相对位置','传统九宫上南下北，北方坎宫在底部正中，南方离宫在顶部正中。将结果与洛书本位比较，可以发现错误排盘常出现了宫位顺序颠倒。']],example:'九运运盘：中9、乾1、兑2、艮3、离4、坎5、坤6、震7、巽8。通过实验室逐步显示九宫即可核对。',mistake:'看到数字要“顺”，便按几何顺时针顺序绕着图形填写。',related:'打开宅盘实验室选择八运，只显示运盘，再逐宫核对这九个数字。',diagram:'flight'},
{aim:'准确说明山盘、向盘和运盘的区别，知道所需的输入数据。',lead:'一张常见玄空宅盘包含运星、山星、向星，每宫共三个数字。完整起盘需要建筑所属元运、坐山、向首以及选择的起盘规则。',sections:[
['三盘回答不同的计算问题','运盘来源于元运。山盘取运盘飞到坐方的数字入中，再按同元龙阴阳决定顺逆。向盘取运盘飞到向方的数字入中，重复对应查表过程。'],
['坐向应相对','二十四山每个坐山与其180°对面的山构成坐向，例如子山午向、癸山丁向。先写清是“坐某向某”，不要以一个方位代替两个概念。'],
['暂不使用复杂边界特殊法','完整传统计算还存在替卦、兼向、五黄入中和历史版本差异。本站下卦演示只在朝向落入山位中间区域且规则明确时输出宅盘，边缘朝向要求补充核验。']],example:'八运子山午向：运盘北方坎宫数4，因此山星从4入中；南方离宫数3，因此向星从3入中。它们的顺逆需要分别查表。',mistake:'因为“子山是阴”，便直接让山星4逆飞，没有查4所属巽卦同元龙山。',related:'在宅盘实验室输入八运、向午180°，观察分步文字和山、向、运三数字的归位。',diagram:'threedisk'},
{aim:'能独立计算指定中心星的顺飞和逆飞九宫，并验证环绕9与1时的循环。',lead:'只要入中数字与飞行方向已确定，后续的数字飞布就是确定性练习，不需要对吉凶作任何判断。',sections:[
['记住不变的飞泊路线','中→乾→兑→艮→离→坎→坤→震→巽。从中宫开始，每走到下一宫填一个数字。'],
['顺飞与逆飞只改变数值','中心4顺飞：乾5、兑6、艮7、离8、坎9、坤1、震2、巽3。中心3逆飞：乾2、兑1、艮9、离8、坎7、坤6、震5、巽4。'],
['用典型宫位验算','中心数、坐宫与向宫应能从清晰的宫位索引重算；若一个宫位错了，优先检查顺逆规则与飞泊顺序。']],example:'八运子山午向，下卦山盘4顺飞、向盘3逆飞；二者在南方离宫都得8，可用标准示例交叉检验。',mistake:'逆飞时从中宫倒着走路线，导致填数与常见下卦规则不一致。',related:'打开宅盘实验室的“山盘”和“向盘”视图，逐宫核算数列。',diagram:'flight'},
{aim:'准确理解“旺山旺向”“双星到向”等只是特定传统体系中的格局术语。',lead:'传统玄空学以当运星出现在坐方、向方的位置关系命名盘局。理解术语之前，先定位当运数在山盘与向盘中各出现在哪里。',sections:[
['找出本运的当令星','八运以8为当运星，九运以9为当运星。观察山盘中8或9落在哪宫，向盘中8或9落在哪宫。'],
['对照传统名词','山盘当运星落坐宫、向盘当运星落向宫，传统称“旺山旺向”；两颗当运星同落向宫称“双星到向”，同落坐宫称“双星到坐”。'],
['说清推论边界','术语属于玄空体系内部的命名规则。它不能推断房屋结构安全、个人事业或财运，更不能用来替代房屋检查、租售调查与施工规范。']],example:'八运子山午向按本站下卦示例，山8与向8都在离宫（向首），因此是“双星到向”的盘面位置关系。',mistake:'将“双星到向”误解为“旺山旺向”，忽略旺山旺向的两星分别落宫要求。',related:'用宅盘中的两种不同坐向比较当运星落位，写下所依据的宫位。',diagram:'pattern'},
{aim:'知道流年星盘的教学计算步骤，并说明公历与节令年界的差别。',lead:'流年飞星与宅盘属于不同层级。本站常见教学示例中，2024年中宫3、2025年中宫2、2026年中宫1，按规定顺飞路线展开九宫。',sections:[
['年度中心星按固定循环','示范公式为：以2024年中宫3为基点，每过一年中心数减1并在1到9循环，2026年的中心为1。该公式便于练习近年排列，传统节令边界仍需另行确认。'],
['逐宫应用洛书路线','中心星确定后，沿中、乾、兑、艮、离、坎、坤、震、巽顺飞递增。每个宫位都要清楚标明所选择的年份，避免把流年星当作固定洛书本位数字。'],
['与宅盘分开记录','宅盘还需要元运与坐向；流年盘单独按年度可画出一张九宫图。两种盘的计算输入不同，不能混为“同一年的房子朝向盘”。']],example:'按本站教学示例，2026年中宫1，乾2、兑3、艮4、离5、坎6、坤7、震8、巽9。',mistake:'把2026年流年中宫1直接当成2026年新建住宅的运盘中心星。',related:'在流年实验室点击2024、2025、2026，观察中宫和南宫数字变化。',diagram:'year'},
{aim:'能够解释同一物理方位为何在不同盘层与不同年份出现不同数字。',lead:'“北方是1”可能指洛书坎宫本位数；“2026北方是6”指2026年的流年飞星；“八运坎宫是4”则指八运运盘。读图先问是哪个层级。',sections:[
['三个输入分支','固定洛书只决定空间宫位；宅盘由起运时间与坐向决定；流年盘由当年中心星决定。按层区分，数字不同就是正常的。'],
['建立一张核对表','每次遇到盘面都记录：图面南北口径、对应时期、建筑坐向、盘层类型、飞泊路径、顺逆依据。只要漏一项，网络图的结果便可能失去解释条件。'],
['处理不同教材的冲突','某些图采用下卦、某些采用替卦，或在立极、年界、方向基准上不同。研究者应保存两个版本及其规则，而非挑一个看上去更吉利的数字。']],example:'同一坎宫：洛书本位1、八运运盘4、2026流年盘6，三个数字属于三个不同对象，因此可同时成立。',mistake:'为了让三张盘一样，擅自替换其中某个数字。',related:'打开三盘对照教学区，把坎宫在三个盘层上的数字记录下来。',diagram:'compare'},
// 25—30 排龙研究
{aim:'能够说明排龙图的基本构成与流派依赖性，识别缺少的输入。',lead:'网络排龙图往往叠有多个箭头、九星吉凶和最后的“旺向”推荐。初学者需要把这些图层拆开，先查计算条件再看结论。',sections:[
['先辨认排龙讨论的对象','传统排龙法可能使用来龙、阴阳、方位和排星起点，并将结果应用到选向。不同书籍与传承有不同的来龙辨认与起排规定，必须保留采用的版本。'],
['与飞星宅盘分层','排龙图中的九星吉凶分类和宅盘里的山星、向星并非同一次运算。名称可能一致，却不应该直接混作一个盘层。'],
['给网络图做来源审查','至少询问：谁绘制？何种流派？来龙从何处起量？依何顺逆？具体星位如何得出？“双山”用何定义？缺少依据时只做结构识别。']],example:'图面写“贪狼吉”，你能识别它属于传统分类；但若没有排龙起点和算法，不应复述为某建筑实际得到贪狼吉龙。',mistake:'只凭红色箭头便推断某栋房子“来龙旺盛”。',related:'将原图拆成二十四山、星名、彩色箭线、右侧结论四层，并逐条写“已知/未知”。',diagram:'layers'},
{aim:'能以图中子、午、卯、酉校正南上北下盘面，再辨认相邻二十四山。',lead:'你最初提供的图把南放在上方、北放在下方、东在左、西在右。方向口径确认后，才可以验证不同箭头指向哪个山。',sections:[
['先认四正','图上方午、下方子、左侧卯、右侧酉。与现代北上地图相比，整张图的南北位置相反。中心放射线应先按这四项定位。'],
['再按每山十五度依次定位','从正北子山0°按顺时针：癸15°、丑30°、艮45°、寅60°、甲75°、卯90°。逆向则是壬345°、亥330°、乾315°等。按角度检查图片指向更可靠。'],
['箭头端点需要测量','图中箭线有不同颜色和粗细，并不等于它们精确落在某一个山位中心。缩放截图可能引入偏差，应用高分辨率矢量底盘重绘坐标后再比较。']],example:'红色“来龙”箭线大致指向西偏南位置，不能只凭其贴近的文字断言准确角度；可将线投影到24等分底盘做测量。',mistake:'把图上的右侧“西”理解成现代地图东侧。',related:'先开高清二十四山图解，再放大原排龙图，逐一确认子、午、卯、酉。',diagram:'mountains2'},
{aim:'能写出排龙计算所需的规则审查表，并指出何时不能继续。',lead:'真正的推演要有可复核的“输入、变换规则、输出”。只背口诀无法查错，尤其是版本不同却使用相同星名的情况。',sections:[
['明确可观测输入','来龙取向、建筑立向、罗盘磁北或真北、度数误差、建筑立极点，必须说明其获取方式。山地现场与城市公寓对于“来龙”的定义也可能不同。'],
['明确术数计算输入','查到具体排龙法的原文与图注后，记录起排星、采用阴阳表、顺逆条件、每步如何移位以及最后“吉凶”的分类依据。'],
['做一份反向复核','别人拿到你写出的起点与表格，应能逐步重算每个方位。如果无法从给定规则推回图中的九星，应该暂停并标注“无法验证”，不自行补写缺失口诀。']],example:'某讲义只有最终图，没有来龙角度与起排诀。可证明的仅有“图层及标注存在”，完整数值推演需补证。',mistake:'将网上A派的顺逆公式套入B派图，得到不同结果后擅自修改箭头。',related:'在“排龙原图研究卡”中列出5项已知与至少3项待查资料。',diagram:'audit'},
{aim:'记住排龙讨论中常见的传统吉凶星名，并了解其与九星数字的对应。',lead:'在部分玄空排龙教材中，贪狼、巨门、武曲、左辅、右弼被归入吉星，禄存、文曲、廉贞、破军归入凶星。该分类属于规定的术数语境。',sections:[
['先将星名匹配到数字','一贪狼、二巨门、三禄存、四文曲、五廉贞、六武曲、七破军、八左辅、九右弼。对照“九星”课程复习，避免只背吉凶忘记编号。'],
['吉与凶属于特定教材内的约定','常见排龙分类为1、2、6、8、9吉，3、4、5、7凶。其他风水分析还包含当运与否、外部形势等说法，不能单凭名称给现实判断。'],
['面对图中的符号先问出处','文字“吉”可以帮助辨识作者的分类，但必须查原文才能断定不同箭线与星名的对应计算正确。']],example:'如果图标出现“七赤破军 凶”，应解释为该排龙版本将七赤归类为凶，不能据此推论坐落其方位的卧室会发生事故。',mistake:'把“文曲在某图为凶”和文学、考试成绩强行联系。',related:'打开九星图，对每颗星标记数字与本教材中的吉凶属性。',diagram:'nineclass'},
{aim:'逐层读取你上传的排龙原图，并用可复核问题检验右侧“旺山吉向”结论。',lead:'原图同时画了24方位、红紫蓝绿箭线、九星名称和选向文字，信息量很大。正确的阅读顺序是先确认底盘，再辨认箭线，最后审查规则与结论。',sections:[
['第一层：基本方位盘','确认图上南下北的布置与二十四山的文字标注，记录子午卯酉四正。按15°重绘中心角，检查图中各个标签是否严格位于对应角度。'],
['第二层：箭线与九星','把红、蓝、紫、绿各画成单独图层，建立“颜色、射线方向、附近山位、对应文字、是否确定”记录表。箭线若恰好压线，须标为不确定。'],
['第三层：选向结论是否有依据','原图右侧提到“午丁、酉辛、子癸、丑艮、卯乙双山之向”。要复原选择过程，应取得排龙起点、顺逆条件、对应表、双山定义和筛选准则。缺一项就只保留图面抄录。']],example:'将原图中的红箭头和吉凶标签隐藏后，你应能独立读出24山；再逐层显示颜色和九星，最后总结目前仍不能核算的环节。',mistake:'把原图最后五组方位当成通用、适用于所有城市与任何住宅的“最佳朝向”。',related:'使用原图放大与研究卡，写出至少两条不能仅凭图片验证的判断。',diagram:'layers'},
{aim:'形成将现场、传统形势、玄空下卦和排龙资料分层呈现的案例报告。',lead:'把不同工具放进一份研究报告时，核心是给每个输出附上“输入从哪里来，计算遵循何种规则，是否得到交叉验证”。',sections:[
['第一章：场地与证据','以地图、照片、规划资料和实测记录描述场地，清楚列出地形、水系、道路、房屋中心、朝向及误差。'],
['第二章：方位与宅盘','记录真北/磁北基准、二十四山角度和边界判断；在适用条件内使用下卦宅盘教学算法，逐宫保存运、山、向三个数字。'],
['第三章：排龙与限制','若有具体传承文本与完整来龙输入，再列出排龙步骤。没有材料时展示“资料缺失”和需补证清单，绝不自动生成吉凶断言。']],example:'模拟住宅给定180°及八运假设，可演示坐子向午的基础下卦盘。若改为186°，虽仍属午山，却偏离山位中心6°，超过本站4.5°支持范围，应停止自动起盘；却不能因为没有实测来龙和历史起用资料就宣称已经得到完整排龙断语。',mistake:'报告只列最终“吉向”，没有方位测量记录、算法规则或证据等级。',related:'导出住宅实训报告，再补入一张来源表和一项误差分析。',diagram:'report'},
// 31—36 案例与研习
{aim:'从权威遗产描述中识别宏村月沼、水系、道路及村落空间的关系。',lead:'宏村是研究传统乡村空间的典型材料。它的照片好看，但图片只能告诉你某一视角的局部。要理解聚落还需要遗产档案、历史地图与现场走访。',sections:[
['事实基础来自遗产资料','宏村与西递构成世界遗产“皖南古村落”。宏村保留传统徽州建筑与村落水系统，月沼、南湖及水渠参与聚落空间组织。'],
['以分层图观察','在总体图上分别描出村落核心、月沼、南湖和主要水渠，再把建筑群与街巷叠加。任何水流方向或历史功能判断都应参考可核对资料。'],
['提出研究性问题','水系如何服务历史日常生活？月沼和街巷怎样构成公共空间？山地气候和徽州民居的形制可能有什么关系？这些问题可以用多种证据回答。']],example:'可确认“宏村有月沼”这类事实；要分析某户人家的坐向或独立排玄空盘仍需实测与建筑年代。',mistake:'凭宏村有水系就声称其居民普遍更富裕，忽略历史制度和经济变量。',related:'进入宏村案例馆，打开遗产资料链接，对照照片写三项可证观察。',diagram:'hongcun'},
{aim:'能够在北京中轴线案例中分清南北方向、礼制空间与现代遗产评价。',lead:'北京中轴线适合学习空间秩序与方向观念。轴线规划的历史意义有资料可考，但将其直接套入风水吉凶公式仍需要额外明确的学术依据。',sections:[
['确认遗产核心对象','北京中轴线是沿历史北京核心南北方向延伸的建筑与公共空间集合，2024年列入世界遗产名录。'],
['观察连续的公共空间','从轴线总体位置入手，注意城市节点、建筑主轴、广场和通行空间之间的层次。与一幢住宅的“朝向”相比，城市轴线涉及多种尺度。'],
['说明不能直接推导的内容','中轴线的规划成就可通过历史地图和申遗档案讨论，但不能凭“朝南”推出某一宫殿当时采用何种玄空盘，也不能用现代年盘重写历史选址过程。']],example:'故宫航拍是轴线上一个关键建筑群的视觉材料，不足以表示整条中轴线的全长与保护范围。',mistake:'把城市整体轴线与某扇大门角度视为完全相同的分析对象。',related:'对照北京中轴线的官方遗产图，指出至少三个空间节点及其南北顺序。',diagram:'axis'},
{aim:'结合可靠资料解释福建土楼的围合结构、共同生活与地形适应。',lead:'福建土楼常见环形和方形等形制，适合研究结构形式、聚居制度和环境适应。传统风水理念可作为建筑文化的一部分，但防御功能有更具体的建筑依据。',sections:[
['识别建筑几何与材料','土楼常采用厚实夯土外围护、多层聚居和中央共同空间，规模、平面与入口设计随具体楼体而异。'],
['观察群居与防御','围合形式有助于理解家族共同生活和历史防御需求；要评价今日安全性，需要结构检测、消防与疏散等工程评估。'],
['与山地环境联合分析','观察土楼与道路、坡地、水源的相对位置，并通过地形资料核对排水与交通。不能把不同土楼的朝向、年代混合成统一结论。']],example:'某张环形土楼照片可支持“存在中央院落”的观察，却不足以确认该建筑的具体元运和风水朝向。',mistake:'将所有土楼理解为相同直径、相同朝向与相同营造年代。',related:'从遗产资料中选定一座具名土楼，把“建筑事实”和“待核实条件”各写三项。',diagram:'tulou'},
{aim:'辨识苏州园林的山水构图、游线与视线组织，并区分借景与具体术数判断。',lead:'苏州古典园林用有限空间组织亭台、廊道、池水、山石与植物。它们构成高度设计化的空间体验，适合观察视线、转折和比例。',sections:[
['先观察空间骨架','从园林平面图找主池、园路、廊道、建筑和假山，并记录进入后第一眼看到什么、哪里形成视线遮挡、哪里出现开敞空间。'],
['理解借景的设计方法','借景是将园外或其他空间中的景物纳入观赏构图。还可以研究框景、漏景及移步换景等传统园林手法，但需要具体园林与可验证视角。'],
['把文化解释和参数分开','园林中的传统宇宙观、山水审美能够经文献研究；实际光照、植物生长与人流承载需要另外测量和评估。']],example:'站在廊道端点拍摄同一池塘，可以比较植被、门洞和亭子的遮挡变化，用照片序列说明移步换景。',mistake:'看到圆形门洞就推论它具有某种普适的吉凶效能。',related:'在苏州园林案例的观察问题中，分别标出一处框景、一处转折与一处水面。',diagram:'garden'},
{aim:'在模拟住宅中独立完成24山判定、坐向求解、九宫覆盖和证据审查。',lead:'案例住宅假设主采光面朝186°，可以确定性地进行山位练习。它没有真实测绘资料，因此所有关于建筑环境的讨论必须基于给定假设或标记待核实。',sections:[
['明确输入条件','模拟建筑平面近似矩形，主要朝向186°（教学给定），暂无正式测绘图、施工年份、磁北校正与周边日照资料。'],
['完成基础计算','186°位于午山172.5°至187.5°，相对反方向6°属子山，按该取向口径为坐子向午。187.5°是相邻丁山的起点，接近界线需要误差复核。'],
['进行五步训练','在案例馆依次完成输入确认、山位判断、边界判断、证据辨析和报告复核。对未确认的起运条件不输出确定“当运宅盘”。']],example:'将朝向改为189°，山位从午变丁，相对坐山由子变癸，但案例给定的186°原始输入仍需要保留。',mistake:'把模拟“已知输入”写成真实现场测量成果。',related:'完成城市住宅5步案例并导出文字报告，然后补写自己的误差分析。',diagram:'flat'},
{aim:'综合审查资料、复核计算结果，提交可以重做的结业研习报告。',lead:'完成36课不意味着永远不会算错。真正的“精通”应体现在能够独立找到依据、核算数据、比较流派，并明确哪些结论仍然有不确定性。',sections:[
['复核输入','确保时间、地点、建筑对象、测向基准、建筑中心、元运与下卦适用范围都明确。任何未确定项都应列入待查清单。'],
['核验计算','将二十四山结果、运盘九数、山盘九数、向盘九数逐项写入报告，给出规则来源。对边界、替卦、排龙图等有争议的内容保留多版本对照。'],
['形成结果与局限','将建筑环境事实、传统象义解释、缺失资料与无法推断事项分列。优先采用可复核照片、历史文献和数字计算，防止把模型内部吉凶写成现实风险断言。']],example:'独立完成八运子山午向下卦宅盘，应算出运盘中8、山盘中4、向盘中3，并逐宫对照已知示例；若方向或分宫不清，应返回相应课程重学。',mistake:'把“36课全部标记完成”当作技能验证，无需再核对例题。',related:'完成所有课末检验、模拟住宅报告，并使用研究检查表自评每一个未获证据支持的判断。',diagram:'report'}
];

