/* 下卦教学：仅对山位中心附近出盘；5入中与替卦条件提示不支持。 */
const v3Flight=['c','nw','w','ne','s','n','sw','e','se'];
const v3Palaces=['se','s','sw','e','c','w','ne','n','nw'];
const v3Pname={se:'巽·东南',s:'离·南',sw:'坤·西南',e:'震·东',c:'中宫',w:'兑·西',ne:'艮·东北',n:'坎·北',nw:'乾·西北'};
const v3State={period:8,bearing:180,view:'all',flightStep:8,caseStep:{},caseQuiz:{}};
function v3BuildZhai(period,bearing){
 const r=XingliCore.house(period,bearing),yuan=XingliCore.at(r.bearing??0).yuan.replace('龙','');
 return {...r,name:r.mountain,sitting:r.sittingMountain,back:r.sitting,centerDist:r.offset,why:r.reason,starHill:r.hill,starFace:r.face,
 sDir:r.sDir?{...r.sDir,name:r.sDir.mountain,yuan}:null,fDir:r.fDir?{...r.fDir,name:r.fDir.mountain,yuan}:null};
}
function v3StarPanel(){let p=v3State.period,a=v3State.bearing,r=v3BuildZhai(p,a),n=mountainInfo(a),phase=v3State.view;
 const select=`<div class="v3-tool-controls"><label>所属元运 <select id="v3-period">${Array.from({length:9},(_,i)=>`<option value="${i+1}" ${p===i+1?'selected':''}>${i+1}运${i===7?' · 2004至2023':i===8?' · 2024至2043':''}</option>`).join('')}</select></label><label>向首方位角 <input id="v3-bearing" type="number" min="0" max="359.99" step="0.5" value="${a}"/></label><div class="v3-quick"><button class="btn btn-small btn-outline" data-v3-example="8|180">八运子山午向</button><button class="btn btn-small btn-outline" data-v3-example="9|90">九运酉山卯向</button><button class="btn btn-small btn-outline" data-v3-example="8|186">边界外示例</button></div></div>`;
 let tabs=['运盘','山盘','向盘','三盘叠加'].map((t,i)=>`<button class="v3-tab ${phase===['luck','hill','face','all'][i]?'active':''}" data-v3-layer="${['luck','hill','face','all'][i]}">${t}</button>`).join('');
 let pad = r.luck?v3Palaces.map(key=>{let lu=r.luck[key],sh=r.starHill?.[key],fa=r.starFace?.[key],stars=phase==='luck'?`<b>${lu}</b>`:phase==='hill'?`<b>${sh??'?'}</b>`:phase==='face'?`<b>${fa??'?'}</b>`:`<div class="v3-three"><em>${sh??'?'}</em><b>${lu}</b><em>${fa??'?'}</em></div>`;return `<div class="v3-cell ${key===r.back?'v3-back':''} ${key===r.facing?'v3-facing':''}"><small>${v3Pname[key]}</small>${stars}<small>${key===r.back?'坐山':key===r.facing?'向首':'　'}</small></div>`}).join(''):'';
 const rows=r.allowed?`<ol><li>向 ${r.name}山 ${fmt(a)}°；坐 ${r.sitting}山；与中心角偏差 ${fmt(r.centerDist)}°。</li><li>${p}运入中顺飞，坐宫${v3Pname[r.back]}得 ${r.sStart}，向宫${v3Pname[r.facing]}得 ${r.fStart}。</li><li>坐山属于${r.sDir.yuan}龙；${r.sStart}星本位同元龙为${r.sDir.name}（${r.sDir.sign>0?'阳顺':'阴逆'}），山盘中心 ${r.sStart}。</li><li>向首属于${r.fDir.yuan}龙；${r.fStart}星本位同元龙为${r.fDir.name}（${r.fDir.sign>0?'阳顺':'阴逆'}），向盘中心 ${r.fStart}。</li></ol>`:`<p class="v3-tool-warning">${r.why}</p>`;
 const afoot=`<p>每宫左侧山星，中间运星，右侧向星。仅用于通行玄空下卦的规则学习。未纳入建筑起用争议、立春边界、替卦、飞线或具体排龙规则，任何数值都不表示实际建筑的吉凶。</p><a href="https://www.cafengshuinet.com/m/show_detail.php?id=940" target="_blank" rel="noopener noreferrer">下卦规则参考 · 刘燮钧《玄空飞星的排法（四）》↗</a>`;
 return `<section class="v3-full-lab card"><div class="eyebrow">COMPLETE PERIOD / MOUNTAIN / FACING</div><div class="v3-lab-header"><div><h2>玄空下卦宅盘 · 分步演算</h2><p>运盘、山盘、向盘三个盘层完整展示。输入元运及向首方位，逐步核对数字来源。</p></div><span class="tag green">可复核计算</span></div>${select}${r.luck?`<div class="v3-layer-tabs">${tabs}</div><div class="v3-zhaipan"><div><div class="v3-axis">↑ 南 · 传统图面 ↑</div><div class="v3-three-grid">${pad}</div><div class="v3-axis">↓ 北 ↓</div></div><div class="v3-explain"><h3>计算过程</h3>${rows}${afoot}</div></div>`:`<div class="v3-zhaipan"><div class="v3-empty">需要调整角度或核实特殊起法。<div>${r.why}</div></div><div class="v3-explain"><h3>无法生成确定三盘</h3>${rows}<p>你仍可以查看独立的运盘和流年演示。输入条件不足时应停止推演。</p></div></div>`}</section>`;
}
