const v2RenderCaseDetail=renderCaseDetail;
renderCaseDetail=function(c){v2RenderCaseDetail(c);const target=$('view-cases').querySelector('.case-detail');if(!target)return;
 const tasks=v3CaseTasks[c.id];if(!tasks)return;
 const record=v3State.caseStep[c.id]||0,completed=gradeData['v3case_'+c.id]||[],idx=Math.min(record,2),q=tasks[idx];let fragment=`<section class="v3-case-trainer"><div class="eyebrow">CASE VERIFICATION</div><h3>案例复核训练 · ${completed.length}/3</h3><p>每项练习对应本案例的明确资料、计算方法或限制条件，答对后保留记录。</p><div class="v3-case-progress">${tasks.map((_,i)=>`<button data-v3-case-step="${i}" data-v3-case-id="${c.id}" class="${idx===i?'selected':''} ${completed.includes(i)?'done':''}">${completed.includes(i)?'✓ ':''}${i+1}. ${['辨认事实','核对方法','说明边界'][i]}</button>`).join('')}</div><p class="v3-case-q">${q[0]}</p><div class="v3-case-choices">${q[1].map((o,i)=>`<button data-v3-case-answer="${i}" data-v3-case-id="${c.id}">${o}</button>`).join('')}</div><div class="checkpoint-feedback" id="v3-case-feedback" aria-live="polite"></div>${completed.length===3?'<p class="v3-success">该案例的3项复核任务已完成。</p>':''}</section>`;target.insertAdjacentHTML('beforeend',fragment);
};
