const v2RenderResources=renderResources;
renderResources=function(){v2RenderResources();let e=document.createElement('div');e.className='v3-source-card card';e.innerHTML=`<div class="eyebrow">METHOD VERIFICATION</div><h3>玄空下卦规则与来源</h3><p>宅盘教学采用运数入中顺飞、山向星取运盘对应宫的星入中、以同元龙阴阳确定顺逆的常见下卦流程。极限角度、替卦以及五黄入中等特例暂不自动计算。</p><a href="https://www.cafengshuinet.com/m/show_detail.php?id=940" rel="noopener noreferrer" target="_blank">刘燮钧《玄空飞星的排法（四）》</a><a href="https://research.xishe.ai/flying-stars" rel="noopener noreferrer" target="_blank">玄空飞星计算过程与八运子山午向验算例</a></div>`;$('view-resources').appendChild(e)};
function v3PailongModal(){let html=`<div class="v3-pailong-detail"><h3>排龙原图研究卡</h3><p>第一层：南上北下、子午卯酉、24等分底盘。第二层：四色箭线与九星名称。第三层：右侧所列“旺山吉向”。这些均可直接辨认。</p><p>仍需补充：排龙版本、来龙取点、起排方法、顺逆条件和双山筛选规则。未取得资料前保留“无法验证”状态。</p>${mountainDiagram()}</div>`;openImageModal(html,'排龙诀图层辨识与证据审查')}
document.addEventListener('click',e=>{
 const ex=e.target.closest('[data-v3-example]');if(ex){const vals=ex.dataset.v3Example.split('|').map(Number);v3State.period=vals[0];v3State.bearing=vals[1];renderStars();return;}
 const layer=e.target.closest('[data-v3-layer]');if(layer){v3State.view=layer.dataset.v3Layer;renderStars();return;}
 const st=e.target.closest('[data-v3-case-step]');if(st){v3State.caseStep[st.dataset.v3CaseId]=Number(st.dataset.v3CaseStep);renderCaseDetail(cases.find(c=>c.id===st.dataset.v3CaseId));return;}
 const an=e.target.closest('[data-v3-case-answer]');if(an){const id=an.dataset.v3CaseId,idx=v3State.caseStep[id]||0,q=v3CaseTasks[id][idx],answer=Number(an.dataset.v3CaseAnswer),feedback=$('v3-case-feedback');if(answer===q[2]){let arr=gradeData['v3case_'+id]||[];if(!arr.includes(idx))arr.push(idx);gradeData['v3case_'+id]=arr;persistGrade();if(feedback){feedback.className='checkpoint-feedback correct';feedback.textContent='回答正确。'+q[3]}setTimeout(()=>{if(state.caseId===id){v3State.caseStep[id]=Math.min(idx+1,2);renderCaseDetail(cases.find(c=>c.id===id))}},500);}else if(feedback){feedback.className='checkpoint-feedback incorrect';feedback.textContent='请重新判断。'+q[3]}return;}
 if(e.target.closest('[data-open-pailong]')){v3PailongModal();return;}
});
document.addEventListener('change',e=>{if(e.target.id==='v3-period'){v3State.period=Number(e.target.value);renderStars();}if(e.target.id==='v3-bearing'){let a=Number(e.target.value);if(Number.isFinite(a)&&a>=0&&a<360){v3State.bearing=a;renderStars();}else toast('角度应在0至360度之间');}});

