for(const [id,title,angle,kind,feature,condition,focus] of v3ExtraCases){
 const m=mountainInfo(angle);
 cases.push({id,type:'sim',title,location:'虚构场景 · 专题教学',period:`教学设定 · 朝向 ${fmt(angle)}°`,summary:`已知方位角 ${fmt(angle)}°。以“${feature}”为观察对象，重点训练${focus}。`,facts:[`模拟建筑参考向首角 ${fmt(angle)}°，在本站为 ${m.m}山；该数值并非真实测量。`,`场景设定：${feature}。`,`需要核实的环境因素：${condition}。`],analysis:[`方位计算：${fmt(angle)}°属于${m.m}山；相对坐山为${m.opposite}山。`,`建筑观察：${condition}。`,`资料要求：${focus}。传统飞星需另外明确元运与适用规则。`],limits:'本案例为虚构数据与抽象图解，不关联真实地名或实际楼盘。日照、安全、运营状况及传统吉凶均不作预测。',question:`请说明朝向 ${fmt(angle)}° 对应哪一山，并列出关于“${condition}”的两个复核动作。`,source:null,kind,angle});
 const i=mountainAt(angle),options=[mountainNames[i],mountainNames[(i+1)%24],mountainNames[(i+23)%24]];
 const opp=mountainNames[(i+12)%24],oppOpts=[mountainNames[(i+11)%24],opp,mountainNames[(i+13)%24]];
 v3CaseTasks[id]=[
  [`模拟朝向 ${fmt(angle)}° 对应什么山？`,options.map(x=>x+'山'),0,`${fmt(angle)}°依据每15°一山的规则划分为${m.m}山。`],
  [`相对坐山是什么？`,oppOpts.map(x=>x+'山'),1,`朝向加180°后得到${m.opposite}山。`],
  [`本案例的“${condition}”应如何处理？`,['先记录数据并按实际资料复核','通过九星数字即可确认','只需参考照片中的颜色'],0,focus+'。']
 ];
}
const v3OriginalRenderCases=renderCases;
renderCases=function(){v3OriginalRenderCases();if(state.caseId)return;
 const countReal=cases.filter(c=>c.type==='real').length,countSim=cases.length-countReal;
 document.querySelectorAll('#view-cases [data-case-filter]').forEach(el=>{let key=el.dataset.caseFilter,labels={all:`全部案例 · ${cases.length}`,real:`文化遗产 · ${countReal}`,sim:`模拟实训 · ${countSim}`};el.textContent=labels[key]});
 const desc=document.querySelector('#view-cases .subtitle');if(desc)desc.textContent=`共${cases.length}个案例：${countReal}个有正式文献的真实遗产与${countSim}个虚构参数实训。案例照片联网加载，专业图解与课程练习可以离线运行。`;
};
const v3BeforeHomeCounts=renderHome;
renderHome=function(){v3BeforeHomeCounts();const stats=document.querySelectorAll('#view-home .stat strong');if(stats.length>=2)stats[1].textContent=String(cases.length).padStart(2,'0');const stage=document.querySelector('#view-home .new-learning-strip .eyebrow');if(stage)stage.textContent='COMPLETE EDITION · 3.0';const sidebarCount=document.querySelector('.nav-item[data-view="cases"] .nav-key');if(sidebarCount)sidebarCount.textContent=String(cases.length).padStart(2,'0');};

