const onlineGallerySelection={};
function onlinePhotoURL(filename,width=1600){return 'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(filename)+'?width='+width;}
function onlineSourceURL(filename){return 'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(filename);}
function onlineGalleryPanel(id){const photos=onlinePhotoSets[id];if(!photos)return '';const a=photos[onlineGallerySelection[id]||0],thumbs=photos.map((p,i)=>`<button type="button" class="online-photo-thumb ${i===(onlineGallerySelection[id]||0)?'active':''}" data-online-photo="${id}" data-online-index="${i}" aria-label="查看${p[0]}" aria-pressed="${i===(onlineGallerySelection[id]||0)}"><img src="${onlinePhotoURL(p[1],380)}" loading="lazy" alt="${p[0]}" onerror="this.style.visibility='hidden'"/><span>${i+1}. ${p[0]}</span></button>`).join('');return `<section class="online-gallery" data-gallery-id="${id}"><div class="online-head"><div><span class="eyebrow">REAL PHOTOGRAPHY · VERIFIED SOURCES</span><h3>实景摄影与多视角研习 <small>${photos.length} 幅</small></h3></div><span class="online-net-indicator">联网影像 · 高清</span></div><div class="online-photo-frame"><div class="online-photo-fallback">${heritageVector(id)}<p>正在加载实景摄影，若图片服务不可达仍可使用矢量示意图。</p></div><img class="online-photo-primary" src="${onlinePhotoURL(a[1])}" alt="${a[0]}" referrerpolicy="no-referrer" onload="this.closest('.online-photo-frame').classList.add('photo-loaded')" onerror="this.closest('.online-photo-frame').classList.add('photo-error')"/><div class="online-photo-status">高清图加载中…</div><button type="button" class="online-magnify" data-online-zoom="${id}">⛶ 高清放大</button></div><div class="online-photo-meta"><div><strong data-online-name>${a[0]}</strong><p data-online-desc>${a[4]}</p><small data-online-credit>摄影：${a[2]}　·　${a[3]}　·　Wikimedia Commons</small></div><a class="online-original" data-online-source href="${onlineSourceURL(a[1])}" target="_blank" rel="noopener noreferrer">查看原图与许可 ↗</a></div><div class="online-photo-thumbs">${thumbs}</div><p class="online-gallery-tip">照片用于观察真实建筑环境，具体方位、地形坡度与建筑立向仍需地图、测绘或现场资料。点击缩略图切换观察角度。</p></section>`;}
function onlineSelectPhoto(id,i){let panel=document.querySelector('.online-gallery[data-gallery-id="'+id+'"]');if(!panel)return;let p=onlinePhotoSets[id][i];onlineGallerySelection[id]=i;const img=panel.querySelector('.online-photo-primary'),frame=panel.querySelector('.online-photo-frame');frame.classList.remove('photo-loaded','photo-error');img.src=onlinePhotoURL(p[1]);img.alt=p[0];panel.querySelector('[data-online-name]').textContent=p[0];panel.querySelector('[data-online-desc]').textContent=p[4];panel.querySelector('[data-online-credit]').textContent=`摄影：${p[2]} · ${p[3]} · Wikimedia Commons`;panel.querySelector('[data-online-source]').href=onlineSourceURL(p[1]);panel.querySelectorAll('.online-photo-thumb').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-pressed',String(j===i));});}
const v31PriorCaseDetail=renderCaseDetail;
renderCaseDetail=function(c){v31PriorCaseDetail(c);if(!onlinePhotoSets[c.id])return;let root=document.querySelector('#view-cases .case-detail');if(!root)return;let oldPhoto=root.querySelector('.photo-wrapper');if(oldPhoto)oldPhoto.remove();const back=root.querySelector('[data-back-cases]');if(back)back.insertAdjacentHTML('afterend',onlineGalleryPanel(c.id));};
document.addEventListener('click',function(e){const t=e.target.closest('[data-online-photo]');if(t){onlineSelectPhoto(t.dataset.onlinePhoto,Number(t.dataset.onlineIndex));return;}const z=e.target.closest('[data-online-zoom]');if(z){const id=z.dataset.onlineZoom,p=onlinePhotoSets[id][onlineGallerySelection[id]||0];openImageModal(`<img src="${onlinePhotoURL(p[1],2560)}" alt="${p[0]}" style="max-width:100%;height:auto"/><p class="caption">${p[0]}　摄影：${p[2]}　许可：${p[3]} · <a href="${onlineSourceURL(p[1])}" target="_blank" rel="noopener noreferrer">查看原始文件、作者与许可信息</a></p>`,p[0]);return;}},true);
