function v32Escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function v32GetMediaURL(a,width=1280){return 'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(a.file)+'?width='+width;}
function v32GetSourceURL(a){return 'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(a.file);}
function v32VisualPanel(i){
 const row=v32CourseVisuals[i],keys=row.photos,st=v32MediaState[i]||{tab:0};
 const media=keys.map((id,index)=>{const a=v32Assets[id];return `<button type="button" class="v32-thumb ${st.tab===index?'active':''}" data-v32-tab="${index}" aria-pressed="${st.tab===index}"><span class="v32-thumb-num">0${index+1}</span><span class="v32-thumb-text"><strong>${v32Escape(a.title)}</strong><small>${a.type}</small></span></button>`;}).join('');
 return `<section class="v32-visual" id="v32-visual" aria-label="第${i+1}课可视化学习">
 <div class="v32-panel-kicker"><span>VISUAL STUDIO · 第 ${String(i+1).padStart(2,'0')} 课</span><span class="v32-pill">来源可追溯</span></div>
 <div class="v32-visual-head"><div><h3>实景与历史资料图研习</h3><p>本课配置两份有来源的资料图，配合课程中的可缩放矢量图，逐步训练观察与推理。</p></div><span class="v32-visual-count">01 / 03</span></div>
 <div class="v32-media-tabs" role="group" aria-label="切换教学图像">${media}<button class="v32-thumb ${st.tab===2?'active':''}" data-v32-tab="2" type="button" aria-pressed="${st.tab===2}"><span class="v32-thumb-num">03</span><span class="v32-thumb-text"><strong>专业矢量图解</strong><small>课程配套 · 可无损放大</small></span></button></div>
 <div id="v32-stage" class="v32-stage"></div>
 <div class="v32-tasks">
  <div class="v32-task-label">看图训练 · 先独立回答，再揭示提示</div>
  <h4>${v32Escape(row.question)}</h4>
  <div class="v32-task-actions"><button type="button" class="btn btn-soft btn-small" data-v32-reveal="hint">${v32Revealed.has(i+':hint')?'收起提示':'显示观察提示'}</button><button type="button" class="btn btn-outline btn-small" data-v32-reveal="answer">${v32Revealed.has(i+':answer')?'收起参考分析':'查看参考分析'}</button></div>
  <div class="v32-hint" id="v32-hint" ${v32Revealed.has(i+':hint')?'':'hidden'}><strong>观察提示</strong><p>${v32Escape(row.hint)}</p></div>
  <div class="v32-answer" id="v32-answer" ${v32Revealed.has(i+':answer')?'':'hidden'}><strong>参考分析</strong><p>${v32Escape(row.answer)}</p></div>
 </div>
 <div class="v32-note-wrap"><label for="v32-notebook">我的图像观察笔记</label><p>记录可核实事实、传统解释与尚需补充的材料；自动保存于本机浏览器。</p><textarea id="v32-notebook" rows="3" placeholder="例如：事实……；需要补充的来源……">${v32Escape(v32VisualNotes[i]||'')}</textarea><div class="v32-note-footer"><span id="v32-note-status">${v32VisualNotes[i]?'已读取本课记录':'可随时继续修改'}</span><button type="button" class="btn btn-small btn-outline" data-v32-export="1">导出36课图像观察笔记</button></div></div>
 </section>`;
}
function v32UpdateStage(){
 const i=state.lesson,row=v32CourseVisuals[i],st=v32MediaState[i]||{tab:0},el=document.getElementById('v32-stage');if(!el)return;
 const panel=document.getElementById('v32-visual');panel.querySelectorAll('[data-v32-tab]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.v32Tab)===st.tab);b.setAttribute('aria-pressed',String(Number(b.dataset.v32Tab)===st.tab));});
 const count=panel.querySelector('.v32-visual-count');if(count)count.textContent=String(st.tab+1).padStart(2,'0')+' / 03';
 if(st.tab===2){el.innerHTML=`<div class="v32-stage-figure"><div class="v32-stage-top"><span>教学自绘 · 动态矢量图</span><span>方位、九宫等数值请与讲义核对</span></div><div class="v32-diagram-host">${defaultDiagram(i)}</div><div class="v32-caption-row"><div><strong>专业图解</strong><p>放大后文字仍清晰。本图是教学示意，不作为历史测量资料。</p></div><button class="btn btn-small btn-outline" type="button" data-v32-zoom-vector>⛶ 全屏放大</button></div></div>`;return;}
 const a=v32Assets[row.photos[st.tab]],url=v32GetMediaURL(a,1500);
 const safe=v32Escape(a.title);
 el.innerHTML=`<div class="v32-stage-figure"><div class="v32-stage-top"><span>${v32Escape(a.type)} · Wikimedia Commons</span><span>照片与历史文献会联网加载</span></div><div class="v32-photo-frame"><div class="v32-loading"><div class="v32-spinner"></div><strong>正在读取馆藏或实景图</strong><small>无法访问图像服务时可切换到专业矢量图</small></div><img class="v32-main-photo" src="${url}" alt="${safe}" referrerpolicy="no-referrer" decoding="async" onload="this.parentElement.classList.add('v32-loaded')" onerror="this.parentElement.classList.add('v32-error')"><div class="v32-image-error"><strong>当前图片未能加载</strong><p>请检查是否可访问 Wikimedia Commons，仍可查看专业矢量图和原始档案。</p><button class="btn btn-small btn-outline" data-v32-tab="2">查看本课矢量图</button></div></div><div class="v32-caption-row"><div><strong>${safe}</strong><p>${v32Escape(a.description)}</p><small>作者 / 摄影：${v32Escape(a.author)}　·　许可：${v32Escape(a.license)}</small></div><div class="v32-caption-buttons"><a href="${v32GetSourceURL(a)}" target="_blank" rel="noopener noreferrer" class="v32-link">原始页面及许可 ↗</a><button type="button" class="btn btn-small btn-outline" data-v32-zoom>⛶ 高清查看</button></div></div></div>`;
 // Clear indeterminate progress state when external image sites hang, without breaking offline diagrams.
 window.setTimeout(()=>{if(!el.isConnected)return;const frame=el.querySelector('.v32-photo-frame');if(frame&&!frame.classList.contains('v32-loaded')&&!frame.classList.contains('v32-error'))frame.classList.add('v32-error');},12000);
}
