document.addEventListener('click',function(ev){
 let t=ev.target.closest('[data-v32-tab]');if(t){const i=state.lesson;v32MediaState[i]={tab:Number(t.dataset.v32Tab)};v32UpdateStage();return;}
 t=ev.target.closest('[data-v32-reveal]');if(t){const i=state.lesson,key=i+':'+t.dataset.v32Reveal;if(v32Revealed.has(key))v32Revealed.delete(key);else v32Revealed.add(key);const el=document.getElementById('v32-'+t.dataset.v32Reveal);if(el)el.hidden=!v32Revealed.has(key);t.textContent=v32Revealed.has(key)?(t.dataset.v32Reveal==='hint'?'收起提示':'收起参考分析'):(t.dataset.v32Reveal==='hint'?'显示观察提示':'查看参考分析');return;}
 t=ev.target.closest('[data-v32-zoom]');if(t){const s=v32MediaState[state.lesson]||{tab:0};const a=v32Assets[v32CourseVisuals[state.lesson].photos[s.tab]];openImageModal(`<img src="${v32GetMediaURL(a,2560)}" alt="${v32Escape(a.title)}" style="display:block;width:100%;height:auto"/><p class="caption">${v32Escape(a.title)} · ${v32Escape(a.author)} · ${v32Escape(a.license)}　<a href="${v32GetSourceURL(a)}" target="_blank" rel="noopener noreferrer">原始资料及授权信息 ↗</a></p>`,a.title);return;}
 t=ev.target.closest('[data-v32-zoom-vector]');if(t){v32ZoomVector();return;}
 t=ev.target.closest('[data-v32-export]');if(t){const exportData={version:'3.2',exported_at:new Date().toISOString(),lessons:lessons.map((l,i)=>({lesson:i+1,title:l[0],visual_notes:v32VisualNotes[i]||'',media:v32CourseVisuals[i].photos.map(k=>({title:v32Assets[k].title,source:v32GetSourceURL(v32Assets[k])}))}))};const obj=new Blob([JSON.stringify(exportData,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(obj);const a=document.createElement('a');a.href=url;a.download='形理书院_36课图像研习笔记.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
},false);
