const v4Options={focus:false,menu:false,index:false,lab:'house'};
const v4Names={home:'探索',courses:'课程',cases:'案例',compass:'罗盘',stars:'飞星实验室',quiz:'测验',resources:'文献'};
function v4Photo(file,width=1400){return 'https://commons.wikimedia.org/wiki/Special:FilePath/'+encodeURIComponent(file)+'?width='+width;}
function v4PhotoByCase(id,width=1300){return onlinePhotoSets[id]?.length?v4Photo(onlinePhotoSets[id][0][1],width):v4Photo('Moon Pond, Hongcun.jpg',width);}
function v4Degree(n){const a=n*Math.PI/180;return {x:240+186*Math.sin(a),y:240-186*Math.cos(a)};}
function v4HeroDisc(){
 const names=['子','癸','丑','艮','寅','甲','卯','乙','辰','巽','巳','丙','午','丁','未','坤','申','庚','酉','辛','戌','乾','亥','壬'];
 const boundaries=Array.from({length:24},(_,i)=>{const a=(i*15-7.5)*Math.PI/180;const r1=149,r2=206;return `<line x1="${240+r1*Math.sin(a)}" y1="${240-r1*Math.cos(a)}" x2="${240+r2*Math.sin(a)}" y2="${240-r2*Math.cos(a)}" stroke="#7c9882" stroke-opacity=".46" stroke-width="1"/>`}).join('');
 const labels=names.map((t,i)=>{const a=i*15*Math.PI/180;return `<text x="${240+177*Math.sin(a)}" y="${244-177*Math.cos(a)}" font-family="Songti SC,STSong,serif" font-size="${i%3===0?17:14}" font-weight="${i%3===0?700:500}" text-anchor="middle" fill="${i===0||i===12?'#175741':'#526d58'}">${t}</text>`}).join('');
 const cardinal=[['北',0],['东',90],['南',180],['西',270]].map(([name,n])=>{const a=n*Math.PI/180;return `<text x="${240+230*Math.sin(a)}" y="${243-230*Math.cos(a)}" text-anchor="middle" font-family="-apple-system,PingFang SC" font-size="12" fill="#54755f" font-weight="700">${name}</text>`}).join('');
 return `<svg class="v4-compass-hero" role="img" aria-label="二十四山教学罗盘，正北子山，顺时针每15度一山" viewBox="0 0 480 480" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="xlDisc" cx="50%" cy="50%" r="50%"><stop stop-color="#fffdf6"/><stop offset=".72" stop-color="#f6f6ec"/><stop offset="1" stop-color="#e4eee4"/></radialGradient></defs><circle cx="240" cy="240" r="209" fill="url(#xlDisc)" stroke="#557c62" stroke-width="1.5"/><circle cx="240" cy="240" r="207" fill="none" stroke="#eff5ea" stroke-width="4"/><circle cx="240" cy="240" r="149" fill="#f6f6ef" stroke="#8eac93" stroke-width="1.4"/>${boundaries}${labels}<circle cx="240" cy="240" r="125" stroke="#91a994" stroke-opacity=".65" stroke-width="1.2" fill="none"/><circle cx="240" cy="240" r="86" stroke="#d4e3d3" stroke-width="1.3" fill="none"/><path d="M240 97L251 240L240 383L229 240Z" fill="#47765b" opacity=".13"/><path d="M240 92L248 240L240 240Z" fill="#c88962"/><path d="M240 388L232 240L240 240Z" fill="#47765b"/><circle cx="240" cy="240" r="30" fill="#e7f0e5" stroke="#80a58a"/><text x="240" y="246" text-anchor="middle" font-size="21" fill="#285d42" font-family="Songti SC,STSong,serif">理</text>${cardinal}<circle cx="240" cy="240" r="207" fill="none" stroke="#5c906c" stroke-opacity=".45"/><circle cx="240" cy="240" r="219" fill="none" stroke="#829e86" stroke-opacity=".18"/></svg>`;
}
function v4CardPhoto(id){const c=cases.find(x=>x.id===id);if(!c)return '';return `<button type="button" class="v4-feature ${id==='hongcun'?'sand':''}" data-case="${c.id}"><div class="v4-feature-icon" aria-hidden="true">${id==='hongcun'?'▧':'◎'}</div><h3>${c.title}</h3><p>${c.summary}</p><b>${c.type==='real'?'历史文化研究':'模拟情境操作'}</b></button>`;}
function v4Home(){const finished=saved.done.length, active=Math.min(35,Math.max(0,state.lesson));let next=lessons[active];const percent=Math.round(finished/36*100);
 const cards=stages.map((st,i)=>{const n=saved.done.filter(x=>x>=6*i&&x<6*(i+1)).length;return `<button class="v4-stage" type="button" data-v4-lesson="${i*6}"><span class="num">CHAPTER ${String(i+1).padStart(2,'0')} / 06</span><span class="arrow">↗</span><strong>${st.name}</strong><small>${st.sub} · ${n}/6节已完成</small><span class="progress-line"><i style="width:${Math.round(n/6*100)}%"></i></span></button>`}).join('');
 document.getElementById('view-home').innerHTML=`<div class="v4-home"><section class="v4-hero"><div class="v4-hero-copy"><span class="v4-kicker">TRADITION & SPACE · 中国传统堪舆研修</span><h1>观山川有形<br><span>见方位之理</span></h1><p>从二十四山到玄空飞星，在真实建筑、历史图版与可操作的推演中，建立完整而审慎的传统文化知识体系。</p><div class="v4-hero-actions"><button class="v4-cta" data-v4-lesson="${active}">${finished?'继续第 '+String(active+1).padStart(2,'0')+' 课':'开始第一课'} <span aria-hidden="true">↗</span></button><button class="v4-textbtn" data-v4-nav="cases">先看实景案例　→</button></div><div class="v4-caption">36节精讲课程　·　30个研习案例　·　交互排盘与学习测验</div></div><div class="v4-hero-graphic">${v4HeroDisc()}<span class="v4-hero-hint">TWENTY-FOUR MOUNTAINS · 360°</span></div></section>
 <section class="v4-resume"><div class="v4-resume-icon" aria-hidden="true">◈</div><div class="v4-resume-info"><small>YOUR LEARNING JOURNEY · 继续研修</small><strong>第${String(active+1).padStart(2,'0')}课　${htmlEscape(next[0])}</strong></div><div class="v4-resume-progress"><div class="track"><div class="track-fill" style="width:${percent}%"></div></div><small>已完成 ${finished} / 36 节</small></div><button class="btn btn-outline btn-small" data-outcomes="overview">我的学习成果 ↗</button><button class="btn btn-outline btn-small" data-v4-lesson="${active}">继续学习 ↗</button></section>
 <div class="section-heading"><div><div class="v4-kicker">YOUR LEARNING EXPERIENCE</div><h2>从理解，到掌握</h2></div><small>清晰的理论 · 可操作的练习 · 可追溯的资料</small></div>
 <div class="v4-featuregrid"><button class="v4-feature dark" type="button" data-v4-nav="courses"><div class="v4-feature-icon" aria-hidden="true">◈</div><h3>系统课程</h3><p>六个阶段，36节精讲，图像资料、示范推演与逐课检验结合。</p><b>36 LESSONS</b></button><button class="v4-feature" type="button" data-v4-nav="cases"><div class="v4-feature-icon" aria-hidden="true">▧</div><h3>案例研习</h3><p>结合传统聚落、真实建筑与模拟练习，观察空间与方位。</p><b>30 CASES</b></button><button class="v4-feature sand" type="button" data-v5-target="v5-tools"><div class="v4-feature-icon" aria-hidden="true">◎</div><h3>工具箱</h3><p>二十四山罗盘、玄空飞星与平面图分析，统一入口、分步学习。</p><b>3 INTERACTIVE TOOLS</b></button></div>
 <div class="section-heading"><div><div class="v4-kicker">STRUCTURED PATH</div><h2>六阶学习路径</h2></div><button class="v4-textbtn" data-v4-lesson="0">从基础开始　↗</button></div><div class="v4-stage-grid">${cards}</div>
 <div class="section-heading"><div><div class="v4-kicker">ARCHITECTURE & HERITAGE</div><h2>走进真实建筑</h2></div><button class="v4-textbtn" data-v4-nav="cases">查看30个案例　↗</button></div><div class="v4-image-feature"><img src="${v4PhotoByCase('hongcun',1800)}" alt="安徽宏村月沼与传统民居实景，来自Wikimedia Commons" loading="lazy" onerror="this.style.display='none'"><div class="v4-image-caption"><div class="v4-kicker" style="color:#e6f0e6">FEATURED CASE · 宏村</div><h3>让古村落成为你的课堂</h3><p>观察水系与建筑空间关系，比较真实摄影和历史资料，学习区分可核实事实与传统解释。</p><button type="button" data-case="hongcun">开始宏村研习　↗</button></div></div>
 <p style="font-size:12px;color:#8b968d;margin:21px 4px 0">研究说明：传统风水术数的吉凶判断缺乏现代科学实证。本站强调文献来源、测量条件与推演规则的边界。</p></div>`;
 v4SyncNav('home');
}
function v4SyncNav(view){document.querySelectorAll('[data-v4-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.v4Nav===view);if(el.classList.contains('v4-navlink'))el.setAttribute('aria-current',el.dataset.v4Nav===view?'page':'false')});const p=document.getElementById('v4-progress');if(p)p.textContent=`${saved.done.length} / 36`;}
function v4OpenLesson(i){if(!Number.isFinite(Number(i)))return;state.lesson=Math.max(0,Math.min(35,Number(i)));v4Options.index=false;document.body.classList.remove('v4-index-open');navigate('courses');}
function v4DecorateCourse(){let root=document.getElementById('view-courses');if(!root)return;let i=state.lesson,st=stages[Math.floor(i/6)],course=root.querySelector('.course-layout');if(!course)return;root.querySelector('.page-intro')?.remove();
 const t=`<div class="v4-course-toolbar"><div class="v4-course-crumb"><span>系统课程</span><span>›</span><strong>${st.name}</strong><span>›</span><span>第 ${String(i+1).padStart(2,'0')} / 36 课</span></div><div class="v4-course-controls"><button type="button" class="v4-toolbtn" data-outcomes="overview">学习成果</button><button type="button" class="v4-toolbtn" data-v4-index aria-expanded="${v4Options.index}">☷　课程目录</button><button type="button" class="v4-toolbtn ${v4Options.focus?'selected':''}" data-v4-focus aria-pressed="${v4Options.focus}">◫　${v4Options.focus?'退出专注':'专注阅读'}</button><button type="button" class="v4-toolbtn" data-v4-prev ${i===0?'disabled':''} aria-label="上一节课">←</button><button type="button" class="v4-toolbtn" data-v4-next ${i===35?'disabled':''} aria-label="下一节课">→</button></div></div><div class="v4-course-progressbar" aria-label="课程顺序进度"><span style="width:${((i+1)/36*100).toFixed(2)}%"></span></div>`;
 root.insertAdjacentHTML('afterbegin',t);document.body.classList.toggle('v4-focused',v4Options.focus);
 let index=course.querySelector('.course-index');if(index){index.insertAdjacentHTML('afterbegin','<div class="v4-index-close"><span>全部36节课程</span><button data-v4-close-index aria-label="关闭目录">×</button></div>');}
 const reading=course.querySelector('.reading-panel');if(reading){const target=reading.querySelector('.reading-body');if(target){const links=[['本课目标','.lesson-callout'],['图像研习','#v32-visual'],['核心讲解','.chapter-section'],['动手练习','.worked-example'],['检验与笔记','.reading-note']];const available=links.filter(([_,sel])=>reading.querySelector(sel));const jumping=`<nav class="v4-lesson-jump" aria-label="本课学习导航">${available.map(([txt,sel],a)=>`<button data-v4-jump="${sel}" type="button">${String(a+1).padStart(2,'0')}　${txt}</button>`).join('')}</nav>`;target.insertAdjacentHTML('afterbegin',jumping);if([4,5,17,35].includes(i))target.insertAdjacentHTML('afterbegin',`<div class="v52-course-task"><strong>${i===35?'结业综合作业':'测向误差实训'}</strong><p>${i===35?'提交带来源、推演步骤和局限说明的案例报告，并按量表自检。':'用一组新的测量读数，判断山位与下卦支持范围；保存可复核的测向记录。'}</p><button class="btn btn-outline" data-outcomes="${i===35?'report':'measurement'}">${i===35?'编写案例报告':'进入测向实训'} →</button></div>`);}}
 v4SyncNav('courses');
}
function v4DecorateCases(){let root=document.getElementById('view-cases');if(!root)return;if(!state.caseId){let headingEl=root.querySelector('.page-intro');let html=`<div class="v4-case-lead"><img src="${v4PhotoByCase('axis',1600)}" alt="北京故宫建筑群的航拍实景" onerror="this.style.display='none'"><div class="v4-case-lead-copy"><span>IMAGE-BASED FIELD STUDY</span><h2>在建筑现场，学习观察。</h2><p>四个有文献的真实遗产案例，二十六个可复核参数的模拟实训，所有判断均说明所依据的资料。</p></div></div>`;if(headingEl){headingEl.insertAdjacentHTML('afterend',html);headingEl.remove();}else root.insertAdjacentHTML('afterbegin',html);}
 v4SyncNav('cases')}
function v4LabToggle(){const root=document.getElementById('view-stars');if(!root)return;const sections=root.querySelectorAll('.interactive-grid,.v3-full-lab');sections.forEach(s=>{s.classList.toggle('v4-lab-hide',v4Options.lab==='house'?s.classList.contains('interactive-grid'):s.classList.contains('v3-full-lab'));});root.querySelectorAll('[data-v4-lab]').forEach(b=>b.classList.toggle('active',b.dataset.v4Lab===v4Options.lab));}
function v4DecorateStars(){let root=document.getElementById('view-stars'),advanced=root.querySelector('.v3-full-lab'),basic=root.querySelector('.interactive-grid');if(!advanced||!basic)return;const headingEl=root.querySelector('.page-intro');const html=`<div class="v4-lab-switcher" role="group" aria-label="飞星实验室模式"><button type="button" data-v4-lab="house" class="${v4Options.lab==='house'?'active':''}">玄空宅盘 · 运山向三盘</button><button type="button" data-v4-lab="year" class="${v4Options.lab==='year'?'active':''}">流年九宫 · 年度演示</button></div>`;if(headingEl)headingEl.insertAdjacentHTML('afterend',html);else root.insertAdjacentHTML('afterbegin',html);if(basic.nextElementSibling===advanced){root.insertBefore(advanced,basic);}v4LabToggle();v4SyncNav('stars')}
