const v4OriginalNavigate=navigate;navigate=function(view,opt){v4OriginalNavigate(view,opt);v4SyncNav(view);if(view!=='courses'){document.body.classList.remove('v4-index-open');v4Options.index=false;document.body.classList.remove('v4-focused');v4Options.focus=false;}};
document.addEventListener('click',function(e){if(e.target.closest('[data-lesson-select]')){v4Options.index=false;document.body.classList.remove('v4-index-open');}let b=e.target.closest('[data-v4-nav]');if(b){e.preventDefault();navigate(b.dataset.v4Nav);document.getElementById('v4-mobile-menu')?.classList.remove('open');document.getElementById('v4-mobile-toggle')?.setAttribute('aria-expanded','false');return;}
 b=e.target.closest('[data-v4-lesson]');if(b){e.preventDefault();v4OpenLesson(b.dataset.v4Lesson);return;}
 b=e.target.closest('[data-v4-index]');if(b){v4Options.index=!v4Options.index;document.body.classList.toggle('v4-index-open',v4Options.index);b.setAttribute('aria-expanded',String(v4Options.index));return;}
 b=e.target.closest('[data-v4-close-index],#v4-index-backdrop');if(b){v4Options.index=false;document.body.classList.remove('v4-index-open');return;}
 b=e.target.closest('[data-v4-focus]');if(b){v4Options.focus=!v4Options.focus;document.body.classList.toggle('v4-focused',v4Options.focus);b.classList.toggle('selected',v4Options.focus);b.textContent=v4Options.focus?'◫　退出专注':'◫　专注阅读';b.setAttribute('aria-pressed',String(v4Options.focus));return;}
 b=e.target.closest('[data-v4-prev]');if(b&&!b.disabled){v4OpenLesson(state.lesson-1);return;}
 b=e.target.closest('[data-v4-next]');if(b&&!b.disabled){v4OpenLesson(state.lesson+1);return;}
 b=e.target.closest('[data-v4-jump]');if(b){let target=document.querySelector('#view-courses '+b.dataset.v4Jump);if(target)target.scrollIntoView({behavior:'smooth',block:'start'});return;}
 b=e.target.closest('[data-v4-lab]');if(b){v4Options.lab=b.dataset.v4Lab;v4LabToggle();return;}
 b=e.target.closest('#v4-search');if(b){openSearch();return;}
 b=e.target.closest('#v4-mobile-toggle');if(b){const m=document.getElementById('v4-mobile-menu');let opened=m.classList.toggle('open');b.setAttribute('aria-expanded',String(opened));return;}
 b=e.target.closest('#v4-top');if(b){window.scrollTo({top:0,behavior:'smooth'});return;}
 });
document.addEventListener('keydown',function(e){if(e.key==='Escape'){v4Options.index=false;document.body.classList.remove('v4-index-open');const m=document.getElementById('v4-mobile-menu');m?.classList.remove('open');document.getElementById('v4-mobile-toggle')?.setAttribute('aria-expanded','false');}});
window.addEventListener('scroll',()=>{const t=document.getElementById('v4-top');if(t)t.classList.toggle('visible',window.scrollY>500)},{passive:true});

init();
